import {PlusIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, FormControl, IconButton, TextInput} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import type {NodeType} from '../../types/app'
import {nodeHandlerRegistry} from '../../service/node-handler-registry'
import type {NodeHandlerMetadata} from '../../types/node-handler-interface'
import {isPostStaffShipFeaturesEnabled} from '../../utils/feature-flags'
import {useLoopOperations} from '../../hooks/use-loop-operations'
import {useState} from 'react'
import styles from './AddNodeButton.module.css'
import {useNodeIDs} from '../../hooks/use-node-ids'
import {inputTypeInfo} from '../../types/input-types'
import {buildNewNode, getNextNodeId} from '../../utils/nodes'
import {useGetLoop} from '../../hooks/use-get-loop'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'

/**
 * Temporary dialog so users can add nodes with custom titles and descriptions.
 * This will be removed once we have a better UI for editing nodes.
 */
function AddNodeDialog({
  onClose,
  onConfirm,
  inputType,
}: {
  onClose: () => void
  onConfirm: (title: string, description: string, inputType?: string) => void
  inputType?: string
}) {
  const [title, setTitle] = useState('')
  const [description, setDescription] = useState('')

  return (
    <Dialog title="Add Node" onClose={onClose} className={styles.dialog}>
      <Dialog.Body className={styles.dialogBody}>
        <FormControl>
          <FormControl.Label>Node Title</FormControl.Label>
          <TextInput
            className={styles.input}
            value={title}
            onChange={e => setTitle(e.target.value)}
            placeholder="New node"
          />
        </FormControl>
        <FormControl>
          <FormControl.Label>Node Description</FormControl.Label>
          <TextInput
            className={styles.input}
            value={description}
            onChange={e => setDescription(e.target.value)}
            placeholder="New node description"
          />
        </FormControl>
      </Dialog.Body>
      <Dialog.Footer>
        <Button onClick={onClose}>Cancel</Button>
        <Button onClick={() => onConfirm(title, description, inputType)} variant="primary">
          Confirm
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}

function InputTypeListItem({
  inputType,
  onSelect,
}: {
  inputType: keyof typeof inputTypeInfo
  onSelect: (type: string) => void
}) {
  const info = inputTypeInfo[inputType]
  const Icon = info.icon

  return (
    <ActionList.Item onSelect={() => onSelect(inputType)}>
      <ActionList.LeadingVisual>
        <Icon />
      </ActionList.LeadingVisual>
      {info.name}
      <ActionList.Description variant="block">{info.description}</ActionList.Description>
    </ActionList.Item>
  )
}

function AddNodeListItem({
  nodeType,
  onSelect,
  onTextInputTypeSelect,
}: {
  nodeType: NodeHandlerMetadata
  onSelect: (type: NodeType) => void
  onTextInputTypeSelect: (inputType: string) => void
}) {
  const Icon = nodeType.icon()

  // Special handling for text nodes to show input type submenu
  if (nodeType.type === 'text') {
    return (
      <ActionMenu>
        <ActionMenu.Anchor>
          <ActionList.Item>
            <ActionList.LeadingVisual>
              {/* eslint-disable-next-line react-hooks/static-components */}
              <Icon />
            </ActionList.LeadingVisual>
            {nodeType.label()}
            <ActionList.Description variant="block">{nodeType.description()}</ActionList.Description>
          </ActionList.Item>
        </ActionMenu.Anchor>
        <ActionMenu.Overlay>
          <ActionList>
            {Object.keys(inputTypeInfo).map(inputType => (
              <InputTypeListItem
                key={inputType}
                inputType={inputType as keyof typeof inputTypeInfo}
                onSelect={onTextInputTypeSelect}
              />
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    )
  }

  return (
    <ActionList.Item onSelect={() => onSelect(nodeType.type)}>
      <ActionList.LeadingVisual>
        {/* eslint-disable-next-line react-hooks/static-components */}
        <Icon />
      </ActionList.LeadingVisual>
      {nodeType.label()}
      <ActionList.Description variant="block">{nodeType.description()}</ActionList.Description>
    </ActionList.Item>
  )
}

export function AddNodeButton() {
  const {getLoop} = useGetLoop()
  const nodeIDs = useNodeIDs()
  const {addNode} = useLoopOperations()
  const [selectedNodeTypeToAdd, setSelectedNodeTypeToAdd] = useState<NodeType>()
  const [selectedInputType, setSelectedInputType] = useState<string>()

  const nodeTypeList = nodeHandlerRegistry.getAllMetadata()
  const enabledNodeTypes = nodeTypeList.filter(nodeType => nodeType.enabled?.() ?? true)

  const {layoutBreakpoint} = useLayoutContext()

  const handleAddNode = (nodeType: NodeType, nodeTitle: string, nodeDescription: string, inputType?: string) => {
    const loop = getLoop()
    if (!loop) return

    const nextId = getNextNodeId(nodeIDs, nodeTitle)
    const node = buildNewNode(nodeType, nextId, nodeTitle, nodeDescription, inputType)
    addNode(node)
  }

  const handleTextInputTypeSelect = (inputType: string) => {
    setSelectedNodeTypeToAdd('text')
    setSelectedInputType(inputType)
  }

  if (!isPostStaffShipFeaturesEnabled()) return null

  return (
    <>
      <ActionMenu>
        <ActionMenu.Anchor>
          <IconButton aria-label="Add node" icon={PlusIcon} variant={layoutBreakpoint ? 'invisible' : 'default'} />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay width="small">
          <ActionList>
            {enabledNodeTypes.map(nodeType => (
              <AddNodeListItem
                key={nodeType.type}
                nodeType={nodeType}
                onSelect={() => setSelectedNodeTypeToAdd(nodeType.type)}
                onTextInputTypeSelect={handleTextInputTypeSelect}
              />
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
      {selectedNodeTypeToAdd && (
        <AddNodeDialog
          onClose={() => {
            setSelectedNodeTypeToAdd(undefined)
            setSelectedInputType(undefined)
          }}
          onConfirm={(title, description, inputType) => {
            handleAddNode(selectedNodeTypeToAdd, title, description, inputType || selectedInputType)
            setSelectedNodeTypeToAdd(undefined)
            setSelectedInputType(undefined)
          }}
          inputType={selectedInputType}
        />
      )}
    </>
  )
}

try{ AddNodeDialog.displayName ||= 'AddNodeDialog' } catch {}
try{ InputTypeListItem.displayName ||= 'InputTypeListItem' } catch {}
try{ AddNodeListItem.displayName ||= 'AddNodeListItem' } catch {}
try{ Icon.displayName ||= 'Icon' } catch {}
try{ AddNodeButton.displayName ||= 'AddNodeButton' } catch {}