import {useLoopsService} from '../contexts/LoopsServiceProvider'
import type {Loop} from '../types/app'
import {useNavigate} from '@github-ui/react-router'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {COPILOT_PATH} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {useGetLoop} from './use-get-loop'
import {useLoopsDispatch} from '../contexts/LoopsStateProvider'
import {useOneTimeBanner} from './use-one-time-banner'

export function useDuplicateLoop() {
  const loopsService = useLoopsService()
  const navigate = useNavigate()
  const {getLoop} = useGetLoop()
  const dispatch = useLoopsDispatch()
  const {showBanner: showDuplicatedBanner} = useOneTimeBanner('duplicated')

  return async () => {
    const loop = getLoop()
    if (!loop) return

    const newLoopId = crypto.randomUUID()
    const duplicatedLoop: Loop = {
      id: newLoopId,
      title: loop.title,
      updatedAt: Date.now(),
      description: loop.description,
      nodes: loop.nodes,
      owned: true,
      visibility: 'private',
    }

    await loopsService.createLoop(duplicatedLoop)

    // Set banner to show after navigation
    showDuplicatedBanner('Loop duplicated successfully.')

    navigate(`${COPILOT_PATH}/l/${newLoopId}`)
    dispatch({type: 'SET_SIDE_PANEL_VIEW', view: 'node'})
  }
}
