import type {NodeType, Node} from '../types/app'

/**
 * Converts a title string to a camelCase ID
 * @param title - The title to convert
 * @returns A camelCase string suitable for use as a node ID
 */
function titleToCamelCaseId(title: string): string {
  return title
    .trim()
    .replace(/[^\w\s]/g, '') // Remove special characters
    .split(/\s+/) // Split on whitespace
    .filter(word => word.length > 0) // Remove empty strings
    .map((word, index) => {
      // First word lowercase, subsequent words capitalized
      if (index === 0) {
        return word.toLowerCase()
      }
      return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
    })
    .join('')
}

/**
 * Generates the next available node ID based on existing node IDs and optionally a title.
 * If a title is provided, tries to generate a camelCase ID from it.
 * Falls back to numeric ID if the title-based ID collides with existing IDs.
 * Always returns a real number if no title is provided or title conversion fails.
 *
 * @param existingNodeIds - Array of existing node IDs
 * @param title - Optional title to base the ID on
 * @returns The next available node ID as a string
 */
export function getNextNodeId(existingNodeIds: string[], title?: string): string {
  if (title) {
    const camelCaseId = titleToCamelCaseId(title)
    if (camelCaseId.length > 0 && !existingNodeIds.includes(camelCaseId)) {
      return camelCaseId
    }
  }

  // Fall back to numeric ID generation
  const maxId = existingNodeIds.reduce((currentMaxId, id) => {
    const parsedId = parseInt(id, 10)
    // Only consider valid numbers for the max calculation
    return isNaN(parsedId) ? currentMaxId : Math.max(currentMaxId, parsedId)
  }, 0)

  return (maxId + 1).toString()
}

export function buildNewNode(type: NodeType, id: string, title: string, description: string, inputType?: string): Node {
  const commonNodeFields = {
    content: '',
    id,
    title,
    description,
  }

  switch (type) {
    case 'loop':
      return {
        ...commonNodeFields,
        type,
        loopId: '',
      }
    case 'text': {
      const inputTypeValue = inputType || 'text'

      // Create the proper InputType structure based on the type
      let metadata
      switch (inputTypeValue) {
        case 'range':
          metadata = {inputType: 'range' as const, min: 0, max: 100}
          break
        case 'boolean':
          metadata = {inputType: 'boolean' as const}
          break
        case 'select':
          metadata = {inputType: 'select' as const, options: []}
          break
        case 'date':
          metadata = {inputType: 'date' as const}
          break
        default:
          metadata = {inputType: 'text' as const}
      }

      return {
        ...commonNodeFields,
        type,
        metadata,
      }
    }
    default:
      return {
        ...commonNodeFields,
        type,
      }
  }
}
