import {validateLoop} from '../service/validate-loop'
import {loopErrorType, type Loop, type LoopErrorType, type LoopValidationError} from '../types/app'
import {getLoopGraph} from './loops'
import type {ValidationContext} from '../types/node-handler-interface'

export const unfixableErrors = new Set<LoopErrorType>([loopErrorType.EmptyInputValue])

/**
 * When a loop has certain errors, we don't want to run autofix since it has a low chance of success.
 */
export function onlyUnfixableErrors(errors: LoopValidationError[]): boolean {
  return errors.length > 0 && errors.every(err => unfixableErrors.has(err.errorType))
}

/**
 * Find the first node in the pipeline with validation errors
 */
export function firstNodeWithValidationErrors(loop: Loop, context?: ValidationContext): string | undefined {
  const validationErrors = validateLoop(loop, context)
  const errorNodes = new Set<string>(
    validationErrors.reduce((prev: string[], current: LoopValidationError) => prev.concat(current.involvedNodes), []),
  )

  // Work through the graph layers so that the error we look at is as early in the pipeline as possible
  const graph = getLoopGraph(loop.nodes)
  for (const layer of graph.layers) {
    for (const node of layer) {
      if (errorNodes.has(node.id)) return node.id
    }
  }

  return undefined
}
