import {useRef} from 'react'
import {Breadcrumbs} from '@github-ui/pacer/Breadcrumbs'
import {LoopsActionMenuOverlay} from './LoopsActionMenuOverlay'

interface LoopBreadcrumbItemProps {
  loopTitle?: string
  loopId?: string
  onDelete: () => void
  onCopyLoop: () => void
  onDuplicate: (loopId: string) => void
  onRename: () => void
}

export function LoopBreadcrumbItem({
  loopTitle,
  loopId,
  onDelete,
  onCopyLoop,
  onDuplicate,
  onRename,
}: LoopBreadcrumbItemProps) {
  const breadcrumbRef = useRef<HTMLButtonElement>(null)

  return (
    <Breadcrumbs.ItemWithMenu
      buttonRef={breadcrumbRef}
      menuOverlay={
        <LoopsActionMenuOverlay
          onDelete={onDelete}
          onCopyLoop={onCopyLoop}
          onDuplicate={onDuplicate}
          onRename={onRename}
          loopId={loopId}
          returnFocusRef={breadcrumbRef}
        />
      }
    >
      {loopTitle || 'Untitled Loop'}
    </Breadcrumbs.ItemWithMenu>
  )
}

try{ LoopBreadcrumbItem.displayName ||= 'LoopBreadcrumbItem' } catch {}