import {useLayoutEffect} from '@github-ui/use-layout-effect'
import {createContext, type PropsWithChildren, useCallback, useContext, useMemo, useRef} from 'react'

type FocusTarget = HTMLElement | null

interface FocusContextData {
  /**
   * Request focus for a named target element.
   * If the target hasn't been registered yet, this will silently no-op.
   * @param targetName - The name of the focus target to focus
   * @param returnTarget - Optional element to return focus to when returnFocus is called
   */
  requestFocus: (targetName: string, returnTarget?: HTMLElement | null) => void

  /**
   * Return focus to the element that was provided when requestFocus was called.
   * @param targetName - The name of the target to return focus from
   * @returns true if focus was successfully returned, false otherwise
   */
  returnFocus: () => boolean

  /**
   * Clear the return target without focusing it.
   * Use this when focus moves away naturally to prevent Shift+Tab from returning later.
   */
  clearReturnTarget: () => void

  /**
   * Register an element as a focus target with a given name.
   * @param targetName - The name to register this target under
   * @param element - The HTML element to focus when requested
   */
  registerFocusTarget: (targetName: string, element: FocusTarget) => void

  /**
   * Remove a focus target from the registry.
   * @param targetName - The name of the target to unregister
   */
  unregisterFocusTarget: (targetName: string) => void
}

const FocusContext = createContext<FocusContextData | undefined>(undefined)

export function FocusProvider({children}: PropsWithChildren) {
  const focusTargetsRef = useRef<Map<string, FocusTarget>>(new Map())
  const returnTargetRef = useRef<HTMLElement | null>(null)

  const requestFocus = useCallback((targetName: string, returnTarget?: HTMLElement | null) => {
    const target = focusTargetsRef.current.get(targetName)
    if (target && document.body.contains(target)) {
      if (returnTarget) {
        returnTargetRef.current = returnTarget
      }
      target.focus()
    }
  }, [])

  const returnFocus = useCallback(() => {
    const returnTarget = returnTargetRef.current
    if (returnTarget && document.body.contains(returnTarget)) {
      returnTarget.focus()
      returnTargetRef.current = null
      return true
    }

    returnTargetRef.current = null
    return false
  }, [])

  const clearReturnTarget = useCallback(() => {
    returnTargetRef.current = null
  }, [])

  const registerFocusTarget = useCallback((targetName: string, element: FocusTarget) => {
    if (element) {
      focusTargetsRef.current.set(targetName, element)
    }
  }, [])

  const unregisterFocusTarget = useCallback((targetName: string) => {
    focusTargetsRef.current.delete(targetName)
  }, [])

  const value = useMemo(
    () => ({requestFocus, returnFocus, clearReturnTarget, registerFocusTarget, unregisterFocusTarget}),
    [requestFocus, returnFocus, clearReturnTarget, registerFocusTarget, unregisterFocusTarget],
  )

  return <FocusContext.Provider value={value}>{children}</FocusContext.Provider>
}

export function useFocusContext() {
  const context = useContext(FocusContext)
  if (!context) {
    throw new Error('useFocusContext must be used within a FocusProvider')
  }
  return context
}

/**
 * Custom hook for registering a focus target using a ref object.
 * Use this when you need to pass a ref to a child component that forwards refs.
 * Automatically handles registration and cleanup.
 *
 * @param targetName - The name to register this focus target under
 * @returns A ref object to pass to your component
 *
 * @example
 * ```tsx
 * function MyComponent() {
 *   const buttonRef = useFocusTargetRef<HTMLButtonElement>('my-button')
 *
 *   return <ExecuteButton ref={buttonRef}>Click me</ExecuteButton>
 * }
 * ```
 */
export function useFocusTargetRef<T extends HTMLElement = HTMLElement>(targetName: string) {
  const {registerFocusTarget, unregisterFocusTarget} = useFocusContext()
  const elementRef = useRef<T>(null)

  useLayoutEffect(() => {
    if (elementRef.current) {
      registerFocusTarget(targetName, elementRef.current)
    }

    return () => {
      unregisterFocusTarget(targetName)
    }
  }, [targetName, registerFocusTarget, unregisterFocusTarget])

  return elementRef
}

try{ FocusContext.displayName ||= 'FocusContext' } catch {}
try{ FocusProvider.displayName ||= 'FocusProvider' } catch {}
try{ MyComponent.displayName ||= 'MyComponent' } catch {}