import {Select, ToggleSwitch} from '@primer/react'
import styles from './NodeInput.module.css'
import {ContentEditor} from '../controls/ContentEditor'
import {DatePicker} from '../controls/DatePicker'
import {useNode} from '../../state/lenses'

interface NodeInputProps {
  className?: string
  content: string
  inputLabelId: string
  nodeId: string
  onChange: (value: string) => void
  compact?: boolean
  readonly?: boolean
}

export function NodeInput({
  content,
  nodeId,
  onChange,
  inputLabelId,
  compact = false,
  readonly = false,
}: NodeInputProps) {
  const node = useNode(nodeId)

  if (!node || node.type !== 'text') return null

  switch (node.metadata.inputType) {
    case 'range':
      return (
        <div className={styles.container}>
          <div className={styles.range}>
            <div className={styles.rangeValue}>{content}</div>
            <div className={styles.rangeContainer}>
              <input
                aria-labelledby={inputLabelId}
                className={styles.rangeInput}
                type="range"
                value={content || '0'}
                min={node.metadata.min}
                max={node.metadata.max}
                onChange={e => onChange(e.target.value)}
                readOnly={readonly}
              />
            </div>
            <div className={styles.rangeLabels}>
              <div className={styles.rangeLabel}>{node.metadata.min}</div>
              <div className={styles.rangeLabel}>{node.metadata.max}</div>
            </div>
          </div>
        </div>
      )

    case 'boolean':
      return (
        <div className={styles.container}>
          <ToggleSwitch
            aria-labelledby={inputLabelId}
            checked={content === 'true'}
            onClick={() => {
              const currentValue = content === 'true'
              const nextValue = currentValue ? 'false' : 'true'
              onChange(nextValue)
            }}
          />
        </div>
      )

    case 'select':
      return (
        <div className={styles.container}>
          <Select
            value={content}
            onChange={e => onChange(e.target.value)}
            disabled={readonly}
            aria-labelledby={inputLabelId}
          >
            {node.metadata.options?.map((option: string) => (
              <Select.Option key={option} value={option}>
                {option}
              </Select.Option>
            ))}
          </Select>
        </div>
      )

    case 'date':
      return (
        <DatePicker value={content} onChange={onChange} placeholder="Select a date..." inputLabelId={inputLabelId} />
      )

    case 'text':
    default:
      return (
        <ContentEditor
          content={content}
          inputLabelId={inputLabelId}
          onUpdate={onChange}
          placeholder="Enter a value"
          compact={compact}
          readonly={readonly}
        />
      )
  }
}

try{ NodeInput.displayName ||= 'NodeInput' } catch {}