// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {CopilotChatState} from '@github-ui/copilot-chat/utils/copilot-chat-reducer'

import {Layout} from './Layout'
import {LoopNotFound} from './LoopNotFound'
import {isLoopError} from '../hooks/queries/loop-error'
import {LoopsServiceProvider} from '../contexts/LoopsServiceProvider'
import {LoopsStateProvider} from '../contexts/LoopsStateProvider'
import {FocusProvider} from '../contexts/FocusContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {ImmersivePlugin} from '@github-ui/copilot-chat/plugin'
import {CHAT_MODE_LOOPS, REFERENCE_TYPE_LOOP} from '../utils/constants'
import {useSynchronizeLoop} from '../hooks/use-synchronize-loop'
import {AppContextProvider} from '../contexts/AppContextProvider'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {useEffect} from 'react'
import {isLoopsPlugin} from '../utils/plugin'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {LoopReference} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {setTitle} from '@github-ui/document-metadata'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getSelectedThread} from '@github-ui/copilot-chat/utils/get-selected-thread'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useDefaultModel} from '@github-ui/copilot-chat/utils/models'
import {useGetLoop} from '../hooks/use-get-loop'
import {useLoopLens} from '../hooks/use-loop-lens'
import {useIsReadonly} from '../hooks/use-is-readonly'
import {useLoop} from '../hooks/queries/use-loop'

export interface LoopProps {
  chatState: CopilotChatState
  plugin: ImmersivePlugin
}

export function Loop({chatState, plugin}: LoopProps) {
  if (!isLoopsPlugin(plugin)) throw new Error('Loop can only be used with a LoopsPlugin')

  return (
    <LoopsServiceProvider value={plugin.service}>
      <LoopInner chatState={chatState} previewUrl={plugin.previewUrl} />
    </LoopsServiceProvider>
  )
}

interface LoopInnerProps {
  chatState: CopilotChatState
  previewUrl?: string
}

function LoopInner({chatState, previewUrl}: LoopInnerProps) {
  const manager = useChatManager()
  const {currentReferences} = chatState
  const thread = getSelectedThread(chatState)
  const {getLoop} = useGetLoop()
  const defaultModel = useDefaultModel(chatState.availableModels)
  const {isReadonly} = useIsReadonly()
  const {error} = useLoop(data => !!data)

  const sendChatMessage = async (message: string) => {
    if (isReadonly) return

    const loop = getLoop()
    if (!loop) return

    const trimmedContent = message.trim()
    if (trimmedContent === '') return

    let references = currentReferences
    if (loop) {
      const loopReference: LoopReference = {type: REFERENCE_TYPE_LOOP, ...loop}
      references = [...references, loopReference]
    }

    manager.sendChatMessage({
      thread,
      content: trimmedContent,
      modeOverride: CHAT_MODE_LOOPS,
      model: defaultModel,
      references,
    })
  }

  if (isLoopError(error) && error.httpStatus === 404) {
    return <LoopNotFound />
  }

  return (
    <AppContextProvider
      availableModels={chatState.modelsLoading.state === 'loaded' ? chatState.availableModels : null}
      defaultModel={defaultModel}
      previewUrl={previewUrl}
      sendChatMessage={sendChatMessage}
    >
      <LoopsStateProvider>
        <FocusProvider>
          <LoopsPreview chatState={chatState} />
        </FocusProvider>
      </LoopsStateProvider>
    </AppContextProvider>
  )
}

function LoopsPreview({chatState}: {chatState: CopilotChatState}) {
  const chatManager = useChatManager()
  const {modelsLoading} = chatState
  const modelsLoadingState = modelsLoading.state
  useSynchronizeLoop(chatState)

  // kick off model request if not already loading
  useEffect(() => {
    if (modelsLoadingState !== 'pending') return

    void chatManager.fetchModels()
  }, [chatManager, modelsLoadingState])

  const loopTitle = useLoopLens(loop => loop?.title)

  useEffect(() => {
    const title = loopTitle ? `${loopTitle} · Loops · GitHub Copilot` : 'Loops · GitHub Copilot'
    setTitle(title)
  }, [loopTitle])

  return <Layout />
}

try{ Loop.displayName ||= 'Loop' } catch {}
try{ LoopInner.displayName ||= 'LoopInner' } catch {}
try{ LoopsPreview.displayName ||= 'LoopsPreview' } catch {}