// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {ChatScrollContainer} from '@github-ui/copilot-chat/components/ChatScrollContainer'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useEntitlement} from '@github-ui/copilot-chat/components/quota/EntitlementContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {FreeChatExceededBanner} from '@github-ui/copilot-chat/components/quota/FreeChatExceededBanner'

import {useRef} from 'react'
import {ChatInput} from './ChatInput'
import {ChatMessages} from './ChatMessages'
import styles from './ChatMessages.module.css'

interface ChatProps {
  isMobileView?: boolean
}

export function Chat({isMobileView}: ChatProps) {
  const inputRef = useRef<HTMLTextAreaElement>(null)
  const {chatQuotaExceeded, isLicensedLimited} = useEntitlement()
  const isInputDisabled = isLicensedLimited && chatQuotaExceeded

  return (
    <div className={styles.container}>
      <ChatScrollContainer disabled={isMobileView} className={styles.scrollContainer}>
        <ChatMessages inputRef={inputRef} />
      </ChatScrollContainer>
      <div className={styles.input}>
        {isInputDisabled ? <FreeChatExceededBanner /> : <ChatInput textAreaRef={inputRef} />}
      </div>
    </div>
  )
}

try{ Chat.displayName ||= 'Chat' } catch {}