// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {ChatInput as SharedChatInput} from '@github-ui/copilot-chat/components/ChatInput'
import type {RefObject} from 'react'
import {useLoopsDispatch} from '../../contexts/LoopsStateProvider'
import {useAppContext} from '../../contexts/AppContextProvider'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatStateLens} from '@github-ui/copilot-chat/CopilotChatContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {ModeSupportName} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useSelectReference} from '../../hooks/use-select-reference'
import {LoopIcon} from '@primer/octicons-react'

interface ChatInputProps {
  textAreaRef: RefObject<HTMLTextAreaElement | null>
}

export function ChatInput({textAreaRef}: ChatInputProps) {
  const dispatch = useLoopsDispatch()
  const {sendChatMessage} = useAppContext()
  const streamingMessage = useChatStateLens(s => s.streamingMessage)

  const handleUserSubmit = async (content: string) => {
    sendEvent('dotcom_chat.activate', {target: 'PANEL_CHAT_MESSAGE_SUBMIT', mode: 'loops'})
    sendChatMessage(content)
    dispatch({type: 'FOCUS_NODE', nodeId: null})
  }

  const selectReference = useSelectReference()

  return (
    <SharedChatInput
      textAreaRef={textAreaRef}
      onSubmit={handleUserSubmit}
      onSelectReference={selectReference}
      modes={[
        {
          name: ModeSupportName.Loops,
          supportsMCP: false,
          supportsAttachments: false,
          supportsModelSwitching: false,
          supportsAutocompletion: true,
          supportsSpaces: false,
          icon: LoopIcon,
          placeholder: 'Refine your loop',
        },
      ]}
      size="large"
      isStreaming={!!streamingMessage}
    />
  )
}

try{ ChatInput.displayName ||= 'ChatInput' } catch {}