import styles from './CompactNodePanel.module.css'
import {sendEvent} from '@github-ui/hydro-analytics'
import {ExecuteButton} from '../../controls/ExecuteButton'
import {InputSection} from '../InputSection'
import {useNodeEdit} from '../../../hooks/use-node-edit'
import {useNodeRunning, useNodeValue} from '../../../state/lenses'
import {NodeContextMenu} from '../../controls/NodeContextMenu'
import {NodeType, NodeLabel} from '../NodeType'
import {Icon} from '@github-ui/pacer/Icon'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports, no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {OutputSection} from '../OutputSection'
import {nodeHandlerRegistry} from '../../../service/node-handler-registry'
import {DuplicateLoopBanner} from '../../shared/DuplicateLoopBanner'
import {useIsReadonly} from '../../../hooks/use-is-readonly'
import {PreviousVersionBanner} from '../../shared/PreviousVersionBanner'
import {ValidationErrorBanner} from '../ValidationErrorBanner'
import {useFocusTargetRef, useFocusContext} from '../../../contexts/FocusContext'
import {useId} from 'react'

function EmptyNodePanel() {
  const {streamingMessage, isWaitingOnCopilot} = useChatState()
  const isStreaming = streamingMessage || isWaitingOnCopilot

  return (
    <div className={styles.panelEmptyState}>
      <Icon icon="node" size={24} />
      {isStreaming ? (
        <span>Select a node in the loop once creation has completed.</span>
      ) : (
        <span>Select a node in the loop to view and edit.</span>
      )}
    </div>
  )
}

function ActiveNodePanel({nodeId, isMobile}: {nodeId: string; isMobile?: boolean}) {
  const {node, isPreparing, onUpdate, runPipelineFromNode, onStop} = useNodeEdit({nodeId})
  const nodeValue = useNodeValue(nodeId)
  const isRunning = useNodeRunning(nodeId) || isPreparing
  const {isReadonly, reason} = useIsReadonly()
  const nodeTitleRef = useFocusTargetRef<HTMLHeadingElement>('node-panel')
  const {returnFocus, clearReturnTarget} = useFocusContext()
  const headingId = useId()

  const handleKeyDown = (event: React.KeyboardEvent) => {
    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
    if (event.shiftKey && event.key === 'Tab' && !isMobile) {
      const didReturn = returnFocus()
      if (didReturn) {
        event.preventDefault()
      }
    }
  }

  const handleBlur = () => {
    // Clear the return target when focus moves away from the heading naturally
    // This ensures Shift+Tab only returns to the canvas node immediately after
    // the programmatic focus, not when the user tabs back to the heading later
    clearReturnTarget()
  }

  if (!node) return null

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <div className={styles.nodeDetails}>
          <div className={styles.nodeTitleContainer}>
            <NodeType type={node.type} node={node} />
            {/* eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions */}
            <h2
              id={headingId}
              ref={nodeTitleRef}
              className={styles.nodeTitleHeading}
              tabIndex={-1}
              onKeyDown={handleKeyDown}
              onBlur={handleBlur}
            >
              <span className={styles.nodeTitleText}>{node.title}</span>
              <NodeLabel type={node.type} node={node} />
            </h2>
          </div>
          <span className={styles.descriptionText}>{node.description}</span>
        </div>
        <div className={styles.nodeActions}>
          {nodeHandlerRegistry.isExecutable(node.type) && (
            <ExecuteButton
              onClick={() => {
                runPipelineFromNode()
                sendEvent('node_action.select', {target: 'PANEL_NODE_RUN', mode: 'loops'})
              }}
              onStop={() => {
                onStop()
                sendEvent('node_action.select', {target: 'PANEL_NODE_STOP', mode: 'loops'})
              }}
              isLoading={isRunning}
              value={nodeValue}
              variant="default"
              iconOnly
            />
          )}
          <NodeContextMenu nodeId={nodeId} />
        </div>
      </div>
      <div className={styles.content}>
        {isReadonly && reason === 'shared' && <DuplicateLoopBanner />}
        {isReadonly && reason === 'previousVersion' && <PreviousVersionBanner />}
        <ValidationErrorBanner nodeId={nodeId} />
        <div className={styles.input}>
          <InputSection nodeId={nodeId} onUpdate={onUpdate} />
        </div>

        <div className={styles.output}>
          {nodeHandlerRegistry.isExecutable(node.type) && (
            <OutputSection
              isRunning={isRunning}
              node={node}
              nodeId={nodeId}
              onRun={runPipelineFromNode}
              onStop={onStop}
            />
          )}
        </div>
      </div>
    </div>
  )
}

interface CompactNodePanelProps {
  nodeId?: string | null
  isMobile?: boolean
}

export function CompactNodePanel({nodeId, isMobile}: CompactNodePanelProps) {
  return nodeId ? <ActiveNodePanel nodeId={nodeId} isMobile={isMobile} /> : <EmptyNodePanel />
}

try{ EmptyNodePanel.displayName ||= 'EmptyNodePanel' } catch {}
try{ ActiveNodePanel.displayName ||= 'ActiveNodePanel' } catch {}
try{ CompactNodePanel.displayName ||= 'CompactNodePanel' } catch {}