import {ActionMenu, ActionList} from '@primer/react'
import type {Node} from '../../types/app'
import styles from './NodeSelector.module.css'

interface NodeSelectorProps {
  nodes: Node[]
  selectedNodeId: string | undefined
  onNodeSelect: (nodeId: string) => void
  label?: string
}

export function NodeSelector({nodes, selectedNodeId, onNodeSelect, label = 'Output'}: NodeSelectorProps) {
  const getNodeDisplayName = (node: Node) => {
    return node.title || node.id
  }

  if (!nodes || nodes.length <= 1) {
    return null
  }

  selectedNodeId = selectedNodeId || nodes[0]?.id
  const selectedNode = nodes.find(node => node.id === selectedNodeId)

  if (!selectedNode) {
    return null
  }

  return (
    <ActionMenu>
      <ActionMenu.Button>
        <span className={styles.label}>{label}: </span>
        {getNodeDisplayName(selectedNode)}
      </ActionMenu.Button>
      <ActionMenu.Overlay width="medium">
        <ActionList selectionVariant="single">
          {nodes.map(node => (
            <ActionList.Item key={node.id} selected={node.id === selectedNodeId} onSelect={() => onNodeSelect(node.id)}>
              {getNodeDisplayName(node)}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

try{ NodeSelector.displayName ||= 'NodeSelector' } catch {}