import {AddNodeButton} from './controls/AddNodeButton'
import {PresetOptionButton} from './controls/PresetOptionButton'
import styles from './CanvasHeader.module.css'
import {CenterAlignButton} from './controls/CenterAlignButton'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useIsReadonly} from '../hooks/use-is-readonly'
import {ActionList, ActionMenu, Button, IconButton} from '@primer/react'
import {PencilIcon, SyncIcon, SquareFillIcon, TasklistIcon} from '@primer/octicons-react'
import {useExecuteButton} from '../hooks/use-execute-button'
import {InputPickerPanel} from './modals/InputPickerPanel'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'

export const ToggleSidePanelButton = () => {
  const {toggleSecondaryColumn, secondaryColumnVisible, layoutBreakpoint} = useLayoutContext()
  if (!layoutBreakpoint) return null
  return (
    <IconButton
      variant={'invisible'}
      aria-label={secondaryColumnVisible ? 'Close Side Panel' : 'Open Side Panel'}
      icon={PencilIcon}
      className={styles.toggleSidePanelCTA}
      onClick={toggleSecondaryColumn}
    />
  )
}

export const ActionButton = () => {
  const {layoutBreakpoint} = useLayoutContext()
  const {isLoading} = useIsReadonly()
  const {
    pipelineRunning,
    hasInputNodes,
    handleRunButtonClick,
    handleStopButtonClick,
    handleRunWithInputs,
    showInputPicker,
    handleInputPickerClose,
    handleInputPickerRun,
  } = useExecuteButton()

  if (!layoutBreakpoint || isLoading) return null

  // For mobile: both owner and readonly viewer can run loop; only hide if layout not mobile or loading
  return (
    <>
      {pipelineRunning ? (
        <IconButton aria-label="Stop loop" icon={SquareFillIcon} variant="danger" onClick={handleStopButtonClick} />
      ) : (
        <ActionMenu>
          <ActionMenu.Anchor>
            <Button aria-label="Loop run actions" variant="primary">
              Run
            </Button>
          </ActionMenu.Anchor>
          <ActionMenu.Overlay>
            <ActionList>
              <ActionList.Item onSelect={handleRunButtonClick}>
                <ActionList.LeadingVisual>
                  <SyncIcon />
                </ActionList.LeadingVisual>
                Run
              </ActionList.Item>
              {hasInputNodes && (
                <ActionList.Item onSelect={handleRunWithInputs}>
                  <ActionList.LeadingVisual>
                    <TasklistIcon />
                  </ActionList.LeadingVisual>
                  Run with custom inputs
                </ActionList.Item>
              )}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      )}
      {showInputPicker && (
        <InputPickerPanel isOpen={showInputPicker} onClose={handleInputPickerClose} onRun={handleInputPickerRun} />
      )}
    </>
  )
}

export function CanvasHeader({centerNodeCanvas}: {centerNodeCanvas: ({duration}: {duration?: number}) => void}) {
  const isDev = process.env.NODE_ENV === 'development'
  const {isReadonly} = useIsReadonly()

  const handleCenterCanvas = () => {
    sendEvent('dotcom_chat.activate', {target: 'CANVAS_HEADER_CANVAS_CENTER', mode: 'loops'})
    centerNodeCanvas({duration: 500})
  }

  return (
    <div className={styles.container}>
      {!isReadonly && <AddNodeButton />}
      {isDev && <PresetOptionButton />}
      <CenterAlignButton onClick={handleCenterCanvas} />
      <ActionButton />
      <ToggleSidePanelButton />
    </div>
  )
}

try{ ToggleSidePanelButton.displayName ||= 'ToggleSidePanelButton' } catch {}
try{ ActionButton.displayName ||= 'ActionButton' } catch {}
try{ CanvasHeader.displayName ||= 'CanvasHeader' } catch {}