import {Banner, Button} from '@primer/react'
import {useNodeValidationErrors} from '../../hooks/use-validation-errors'
import {useAppContext} from '../../contexts/AppContextProvider'
import {createNodeErrorMessage} from '../../utils/loop-error-messages'
import {sendEvent} from '@github-ui/hydro-analytics'
import styles from './ValidationErrorBanner.module.css'

interface ValidationErrorBannerProps {
  nodeId: string
}

export function ValidationErrorBanner({nodeId}: ValidationErrorBannerProps) {
  const validationErrors = useNodeValidationErrors(nodeId)
  const {sendChatMessage} = useAppContext()

  if (validationErrors.length === 0) {
    return null
  }

  const handleFixClick = () => {
    const combinedError = validationErrors.join('; ')
    const message = createNodeErrorMessage(nodeId, combinedError)
    sendChatMessage(message)
    sendEvent('dotcom_chat.activate', {target: 'PANEL_NODE_FIX_VALIDATION_ERROR', mode: 'loops'})
  }

  const description =
    validationErrors.length === 1 ? (
      validationErrors[0]
    ) : (
      <ul className={styles.errorList}>
        {validationErrors.map(error => (
          <li key={error}>{error}</li>
        ))}
      </ul>
    )

  return (
    <Banner
      variant="warning"
      title="Configuration Error"
      hideTitle
      description={description}
      primaryAction={
        <Button onClick={handleFixClick} size="small">
          Fix with Copilot
        </Button>
      }
    />
  )
}

try{ ValidationErrorBanner.displayName ||= 'ValidationErrorBanner' } catch {}