// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports, no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {CopilotNavigationWithContext} from '@github-ui/copilot-chat/components/navigation/CopilotNavigation'
import {Layout as PacerLayout} from '@github-ui/pacer/Layout'

import {Banners} from './Banners'
import {Canvas} from './Canvas'
import {ComponentErrorBoundary} from './ComponentErrorBoundary'
import {LeftHeader, RightHeader} from './Header'
import {LoopEmptyState} from './LoopEmptyState'
import {LoopPlaceholder} from './LoopPlaceholder'
import {OutputView} from './OutputView'
import {SidePanel} from './SidePanel'
import {useLoopLens} from '../hooks/use-loop-lens'
import {useLoopsStateLens} from '../contexts/LoopsStateProvider'
import styles from './Layout.module.css'
import {ViewToggle} from './controls/ViewToggle'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'

function RightColumn({currentView}: {currentView: 'canvas' | 'output'}) {
  const {layoutBreakpoint: isMobileView} = useLayoutContext()
  return (
    <ComponentErrorBoundary name="canvas">
      {isMobileView && <ViewToggle />}
      {currentView === 'output' ? <OutputView /> : <Canvas />}
    </ComponentErrorBoundary>
  )
}

/**
 * Future Loops layout component using Pacer components. Not quite ready for production/staff ship yet.
 */
export function Layout() {
  const hasCurrentLoop = useLoopLens(loop => !!loop)
  const hasCurrentLoopGraph = useLoopLens(loop => !!loop?.nodes && loop.nodes.length > 0)
  const selectedNodeId = useLoopsStateLens(s => s.focusedNodeId)
  const currentView = useLoopsStateLens(s => s.view)
  const {streamingMessage, isWaitingOnCopilot} = useChatState()
  const showLoopPlaceholder = streamingMessage || isWaitingOnCopilot

  return (
    <>
      <Banners />
      <PacerLayout mainColumn="right" mobileSecondaryColumnDirection="vertical">
        <PacerLayout.Header>
          <PacerLayout.HeaderLeft className={styles.headerLeft}>
            <LeftHeader />
          </PacerLayout.HeaderLeft>
          <PacerLayout.HeaderRight className={styles.headerRight}>
            <RightHeader />
          </PacerLayout.HeaderRight>
        </PacerLayout.Header>

        <PacerLayout.Sidebar>
          <CopilotNavigationWithContext />
        </PacerLayout.Sidebar>

        <PacerLayout.ColumnLeft>
          <ComponentErrorBoundary name="side-panel">
            <SidePanel nodeId={selectedNodeId} />
          </ComponentErrorBoundary>
        </PacerLayout.ColumnLeft>

        <PacerLayout.ColumnRight className={styles.columnRight}>
          {showLoopPlaceholder ? (
            <LoopPlaceholder />
          ) : hasCurrentLoopGraph ? (
            <RightColumn currentView={currentView} />
          ) : hasCurrentLoop ? (
            <LoopEmptyState />
          ) : null}
        </PacerLayout.ColumnRight>
      </PacerLayout>
    </>
  )
}

try{ RightColumn.displayName ||= 'RightColumn' } catch {}
try{ Layout.displayName ||= 'Layout' } catch {}