import {useRef, useState} from 'react'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {VersionName} from '@github-ui/copilot-chat/components/VersionName'
import {ActionMenu} from '@primer/react'
import {Tooltip} from '@primer/react/next'

import styles from './VersionSelector.module.css'
import {useLoopVersions} from '../../hooks/queries/use-loop-versions'
import {useSelectedVersion} from '../../hooks/use-selected-version'
import {useLoopIsRunning} from '../../state/lenses'
import {VersionList} from './VersionList'

export function VersionSelector() {
  const {isLoading} = useLoopVersions()
  const {selectedVersion} = useSelectedVersion()
  const isRunning = useLoopIsRunning()
  const selectedItemRef = useRef<HTMLLIElement>(null)
  const [isOpen, setIsOpen] = useState(false)

  const handleOpenChange = (open: boolean) => {
    if (isRunning && open) return

    setIsOpen(open)

    if (!open) return

    setTimeout(() => {
      if (!selectedItemRef.current) return
      selectedItemRef.current?.scrollIntoView({
        behavior: 'instant',
        block: 'nearest',
      })
    })
  }

  if (!isLoading && !selectedVersion) return null

  const actionMenuButton = (
    <ActionMenu.Button variant="invisible" className={styles.anchor} loading={isLoading}>
      <VersionName version={selectedVersion ?? ''} data-testid="version-selector" />
    </ActionMenu.Button>
  )

  return (
    <ActionMenu onOpenChange={handleOpenChange} open={isOpen}>
      {isRunning ? (
        <Tooltip text="Version cannot be changed while the loop is running.">{actionMenuButton}</Tooltip>
      ) : (
        actionMenuButton
      )}

      <ActionMenu.Overlay className={styles.overlay}>
        <VersionList />
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

try{ VersionSelector.displayName ||= 'VersionSelector' } catch {}