import {useNode} from '../state/lenses'
import type {Node} from '../types/app'
import {getOutputNodes, sanitizeNode} from '../utils/loops'
import {useRunPipeline} from './use-run-pipeline'
import {useLoopOperations} from './use-loop-operations'
import {useHasValidationErrors} from './use-validation-errors'
import {useLoopLens} from './use-loop-lens'
import {useGetLoop} from './use-get-loop'

export function useNodeEdit({nodeId}: {nodeId: string}) {
  const {getLoop} = useGetLoop()
  const {runPipeline, stopPipeline, isPreparing} = useRunPipeline()
  const {updateNode} = useLoopOperations()
  const hasValidationErrors = useHasValidationErrors()
  const isOutput = useLoopLens(loop => loop && getOutputNodes(loop).some(n => n.id === nodeId))

  const node = useNode(nodeId)

  const runPipelineFromNode = async () => {
    if (hasValidationErrors) return
    if (!node) return

    const currentLoop = getLoop()
    if (!currentLoop) return

    runPipeline(currentLoop, node.id)
  }

  const onUpdate = (updates: Partial<Node>) => {
    if (!node) return

    const sanitizedNode = sanitizeNode({...node, ...updates} as Node, [])
    if (!sanitizedNode) return

    updateNode(node.id, sanitizedNode)
  }

  return {
    isOutput,
    isPreparing,
    node,
    runPipelineFromNode,
    onUpdate,
    onStop: stopPipeline,
  }
}
