import {useNodeValue, useLoopIsRunning} from '../state/lenses'
import {useRunPipeline} from '../hooks/use-run-pipeline'
import {useValidationErrors} from '../hooks/use-validation-errors'
import {useExecution} from '../hooks/queries/use-execution'
import {getOutputNodes} from '../utils/loops'
import {sendEvent} from '@github-ui/hydro-analytics'
import {logError} from '../utils/console'
import styles from './OutputView.module.css'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {stringifyNodeValue} from '../utils/utils'
import {ExecutionView} from './shared/ExecutionView'
import {useGetLoop} from '../hooks/use-get-loop'
import {useLoopLens} from '../hooks/use-loop-lens'
import {clsx} from 'clsx'
import {Button, LinkButton} from '@primer/react'
import {CopilotIcon, WorkflowIcon} from '@primer/octicons-react'
import {useLoopsDispatch} from '../contexts/LoopsStateProvider'
import {useState, type MouseEvent} from 'react'
import {NodeSelector} from './controls/NodeSelector'
import {useNavigate} from '@github-ui/use-navigate'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {useGetExecution} from '../hooks/use-get-execution'
import {makeLoopExecutionReference} from '../utils/loop-execution-reference'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'

export function OutputView() {
  const manager = useChatManager()
  const navigate = useNavigate()
  const dispatch = useLoopsDispatch()

  const allOutputNodes = useLoopLens(loop => {
    if (!loop) return []
    return getOutputNodes(loop)
  })

  const [selectedNodeId, setSelectedNodeId] = useState(() => {
    if (allOutputNodes && allOutputNodes.length > 0) {
      const firstNode = allOutputNodes[0]
      if (firstNode) {
        return firstNode.id
      }
    }
  })

  const selectedNode = allOutputNodes?.find(node => node.id === selectedNodeId) || allOutputNodes?.[0]

  const {getLoop} = useGetLoop()
  const {getExecution} = useGetExecution()
  const {isPreparing, runPipeline, stopPipeline} = useRunPipeline()
  const nodeValue = useNodeValue(selectedNode?.id || '')

  const {
    data: nodeError,
    isLoading: isExecutionLoading,
    isEnabled: isExecutionQueryEnabled,
  } = useExecution(execution => {
    if (!execution) return null
    return (
      Object.values(execution.nodes)
        .map(nodeState => nodeState?.error)
        .find(error => error) || null
    )
  })
  const isLoading = isExecutionLoading || !isExecutionQueryEnabled

  const allValidationErrors = useValidationErrors()
  const validationErrors = allValidationErrors.map(error => error.error)
  const isLoopRunning = useLoopIsRunning() || isPreparing
  const valueString = stringifyNodeValue(nodeValue)
  // Show header only when there's an output value to display.
  // (Previously also showed when there were no output nodes for placeholder purposes.)
  const shouldShowHeader = !!valueString

  const handleNodeSelection = (nodeId: string) => {
    setSelectedNodeId(nodeId)
    sendEvent('dotcom_chat.activate', {target: 'OUTPUT_VIEW_NODE_SELECT', mode: 'loops'})
  }

  const handleRun = async () => {
    const currentLoop = getLoop()
    if (!currentLoop) return
    try {
      await runPipeline(currentLoop)
      sendEvent('dotcom_chat.activate', {target: 'OUTPUT_VIEW_RUN', mode: 'loops'})
    } catch (error) {
      logError('Failed to run pipeline:', error)
    }
  }

  const handleStop = () => {
    stopPipeline()
    sendEvent('dotcom_chat.activate', {target: 'OUTPUT_VIEW_STOP', mode: 'loops'})
  }

  const handleViewGraphClick = () => {
    dispatch({type: 'SET_VIEW', view: 'canvas'})
    sendEvent('dotcom_chat.activate', {
      target: 'ERROR_VIEW_GRAPH',
      mode: 'loops',
    })
  }

  const askAboutOutput = async (e: MouseEvent) => {
    e.preventDefault()

    const loop = getLoop()
    const execution = getExecution()
    if (!loop || !execution) return

    await manager.selectThread(null)
    manager.addReference(makeLoopExecutionReference(loop, execution), 'loop-output-view')
    navigate('/copilot')
  }

  const viewCanvasButton = (
    <Button leadingVisual={WorkflowIcon} onClick={handleViewGraphClick}>
      View graph
    </Button>
  )

  return (
    <div className={clsx(styles.container, styles.v2)}>
      <h2 className="sr-only">Output</h2>
      <div className={styles.card}>
        {shouldShowHeader && (
          <div className={styles.header}>
            <div className={styles.headerLeftSide}>
              <NodeSelector
                nodes={allOutputNodes || []}
                selectedNodeId={selectedNodeId}
                onNodeSelect={handleNodeSelection}
                label="Output"
              />
            </div>
            <div className={styles.headerRightSide}>
              {copilotFeatureFlags.loopExecutionReferences && (
                <LinkButton href="/copilot" leadingVisual={CopilotIcon} onClick={askAboutOutput}>
                  Chat
                </LinkButton>
              )}
              <CopyToClipboardButton ariaLabel="Copy output" textToCopy={valueString} />
            </div>
          </div>
        )}
        <div className={styles.scrollContainer}>
          <div className={styles.content}>
            <ExecutionView
              outputNodeExists={allOutputNodes.length > 0}
              isRunning={isLoopRunning}
              isLoading={isLoading}
              nodeValue={nodeValue}
              nodeError={nodeError ?? null}
              validationErrors={validationErrors}
              additionalActions={viewCanvasButton}
              onRun={handleRun}
              onStop={handleStop}
            />
          </div>
        </div>
      </div>
      <h2 className="sr-only">End of output</h2>
    </div>
  )
}

try{ OutputView.displayName ||= 'OutputView' } catch {}