import {LinkIcon, ShareAndroidIcon} from '@primer/octicons-react'
import {Button, Dialog, FormControl, IconButton, Radio, RadioGroup} from '@primer/react'
import {useCallback, useRef, useState} from 'react'
import {copyText} from '@github-ui/copy-to-clipboard'
import {useQueryClient} from '@github-ui/react-query'
import {useLoopID} from '../state/lenses'
import {useLoopsService} from '../contexts/LoopsServiceProvider'
import {useLoopLens} from '../hooks/use-loop-lens'
import {getLoopQueryKey} from '../hooks/queries/use-loop'
import {draftVersion} from '../utils/versions'
import type {Loop} from '../types/app'
import styles from './LoopShareButton.module.css'
import {useIsReadonly} from '../hooks/use-is-readonly'
import {useOneTimeBanner} from '../hooks/use-one-time-banner'
import type {SharingMode} from '../types/sharing'

export function LoopShareButton() {
  const [dialogOpen, setDialogOpen] = useState(false)
  const [sharingMode, setSharingMode] = useState<SharingMode>('only-me')
  const returnFocusRef = useRef<HTMLButtonElement>(null)
  const loopID = useLoopID()
  const loopsService = useLoopsService()
  const loopVisibility = useLoopLens(loop => loop?.visibility)
  const queryClient = useQueryClient()
  const {showBanner: showLinkCopiedBanner} = useOneTimeBanner('linkCopied')
  const {isReadonly, isLoading} = useIsReadonly()

  const openDialog = useCallback(() => {
    setDialogOpen(true)

    if (loopVisibility === 'public') {
      setSharingMode('anyone')
    } else {
      setSharingMode('only-me')
    }
  }, [loopVisibility])

  const closeDialog = useCallback(() => {
    setDialogOpen(false)
  }, [])

  const handleSharingModeChange = useCallback((value: string | null) => {
    if (!value) return
    setSharingMode(value as SharingMode)
  }, [])

  const copyShareLink = useCallback(async () => {
    if (loopID && sharingMode === 'anyone') {
      const loopsUrl = `${window.location.origin}/copilot/l/${loopID}`
      await copyText(loopsUrl)
      showLinkCopiedBanner('Link copied to your clipboard.')
      closeDialog()
    }
  }, [loopID, sharingMode, showLinkCopiedBanner, closeDialog])

  const handleSave = useCallback(async () => {
    if (loopID) {
      let newVisibility: 'public' | 'private'

      if (sharingMode === 'anyone') {
        await loopsService.shareLoop(loopID)
        newVisibility = 'public'
      } else {
        await loopsService.unshareLoop(loopID)
        newVisibility = 'private'
      }

      // Update the cache to reflect the new visibility
      const queryKey = getLoopQueryKey(loopID, draftVersion)
      queryClient.setQueryData(queryKey, (oldData: Loop | null | undefined) => {
        if (oldData && typeof oldData === 'object') {
          return {
            ...oldData,
            visibility: newVisibility,
          }
        }
        return oldData
      })

      if (newVisibility === 'public') {
        copyShareLink()
      }
      closeDialog()
    }
  }, [loopID, sharingMode, queryClient, closeDialog, loopsService, copyShareLink])

  if (isReadonly || isLoading) return null

  return (
    <>
      <IconButton
        ref={returnFocusRef}
        icon={ShareAndroidIcon}
        onClick={openDialog}
        size="medium"
        aria-label="Share loop"
        tooltipDirection="s"
      />

      {dialogOpen && (
        <Dialog title="Share loop" onClose={closeDialog} width="large" returnFocusRef={returnFocusRef}>
          <div>
            <RadioGroup name="sharing-mode" onChange={handleSharingModeChange}>
              <RadioGroup.Label visuallyHidden>Sharing options</RadioGroup.Label>
              <FormControl>
                <Radio value="anyone" checked={sharingMode === 'anyone'} />
                <FormControl.Label className={styles.radioLabel}>Anyone with link</FormControl.Label>
                <FormControl.Caption>Everyone can access your loop through the link</FormControl.Caption>
              </FormControl>
              <FormControl className={styles.radioOption}>
                <Radio value="only-me" checked={sharingMode === 'only-me'} />
                <FormControl.Label className={styles.radioLabel}>Only me</FormControl.Label>
                <FormControl.Caption>Only you have access to your loop</FormControl.Caption>
              </FormControl>
            </RadioGroup>

            <hr className={styles.divider} />

            <div className={styles.actions}>
              <Button leadingVisual={LinkIcon} onClick={copyShareLink} inactive={loopVisibility === 'private'}>
                Copy link
              </Button>
              <Button variant="primary" onClick={handleSave}>
                Save
              </Button>
            </div>
          </div>
        </Dialog>
      )}
    </>
  )
}

try{ LoopShareButton.displayName ||= 'LoopShareButton' } catch {}