import type {Loop, TextNode} from '../types/app'
import {getInputIds} from './loops'

/**
 * Check if a text node is a pure input node (doesn't reference other nodes)
 */
function isPureInputNode(node: TextNode): boolean {
  return getInputIds(node).size === 0
}

/**
 * Get all text nodes that are pure input nodes (don't reference other nodes)
 */
export function getInputNodes(loop: Loop): TextNode[] {
  return loop.nodes.filter((node): node is TextNode => {
    return node.type === 'text' && isPureInputNode(node)
  })
}

/**
 * Get default values from input nodes' content
 */
export function getInputNodeDefaults(loop: Loop): Record<string, string> {
  const defaults: Record<string, string> = {}

  for (const node of loop.nodes) {
    if (node.type === 'text' && isPureInputNode(node)) {
      defaults[node.id] = node.content || ''
    }
  }

  return defaults
}

/**
 * Create a modified loop with overridden input values
 */
export function applyInputOverrides(loop: Loop, inputOverrides: Record<string, string>): Loop {
  const modifiedNodes = loop.nodes.map(node => {
    // Only override text nodes that have overrides and are pure input nodes
    if (node.type === 'text' && node.id in inputOverrides && isPureInputNode(node)) {
      return {
        ...node,
        content: inputOverrides[node.id] || node.content,
      }
    }
    return node
  })

  return {
    ...loop,
    nodes: modifiedNodes,
  }
}
