import {IconButton} from '@primer/react'
import {FocusCenterIcon} from '../CustomIcon'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'

interface CenterAlignButtonProps {
  onClick: (e: React.MouseEvent<HTMLButtonElement>) => void
}

export function CenterAlignButton({onClick}: CenterAlignButtonProps) {
  const {layoutBreakpoint} = useLayoutContext()
  // On mobile, we always use the invisible variant to match the design
  // otherwise we use the default variant
  return (
    <IconButton
      variant={layoutBreakpoint ? 'invisible' : 'default'}
      aria-label={'Set center alignment'}
      icon={FocusCenterIcon}
      onClick={e => onClick(e)}
    />
  )
}

try{ CenterAlignButton.displayName ||= 'CenterAlignButton' } catch {}