import {SegmentedControl} from '@primer/react'
import {EyeIcon} from '@primer/octicons-react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useLoopsDispatch, useLoopsStateLens} from '../../contexts/LoopsStateProvider'
import styles from './ViewToggle.module.css'
import {DiagramIcon} from '../CustomIcon'

export function ViewToggle() {
  const view = useLoopsStateLens(s => s.view)
  const dispatch = useLoopsDispatch()

  const handleViewChange = (index: number) => {
    let newView: 'canvas' | 'output'
    let target: string

    if (index === 0) {
      newView = 'canvas'
      target = 'HEADER_SELECT_CANVAS'
    } else {
      newView = 'output'
      target = 'HEADER_SELECT_OUTPUT'
    }

    dispatch({type: 'SET_VIEW', view: newView})
    sendEvent('dotcom_chat.activate', {
      target,
      mode: 'loops',
    })
  }

  return (
    <div className={styles.viewToggleWrapper}>
      <SegmentedControl className={styles.viewToggle} aria-label="View toggle" onChange={handleViewChange}>
        <SegmentedControl.Button key="canvas-full" leadingIcon={DiagramIcon} selected={view === 'canvas'}>
          Graph
        </SegmentedControl.Button>
        <SegmentedControl.Button key="output-full" leadingIcon={EyeIcon} selected={view === 'output'}>
          Output
        </SegmentedControl.Button>
      </SegmentedControl>
    </div>
  )
}

try{ ViewToggle.displayName ||= 'ViewToggle' } catch {}