import {ContentEditor} from './ContentEditor'
import type {Extension} from '@codemirror/state'
import {createNodeAutocompleteExtension} from '../../utils/code-mirror-extensions/node-autocomplete'
import {useLoopLens} from '../../hooks/use-loop-lens'
import {createNodeReferenceHighlighter} from '../../utils/code-mirror-extensions/node-reference-highlighter'
import {FormControl} from '@primer/react'
import styles from './ContentEditorWithAutocomplete.module.css'

export const ContentEditorWithAutocomplete = ({
  className,
  content,
  onUpdate,
  placeholder = 'Enter a prompt',
  extensions,
  nodeId,
  inputLabelId,
  compact = false,
  readonly = false,
}: {
  className?: string
  content: string
  onUpdate?: (content: string) => void
  placeholder?: string
  extensions?: Extension[]
  nodeId?: string
  inputLabelId: string
  compact?: boolean
  readonly?: boolean
}) => {
  const nodes = useLoopLens(pipeline => pipeline?.nodes ?? [])
  const nodeAutocomplete = createNodeAutocompleteExtension(() => nodes, nodeId)
  const nodeReferenceHighlighter = createNodeReferenceHighlighter(() => nodes, nodeId)
  const allExtensions = [...(extensions ?? []), nodeAutocomplete, nodeReferenceHighlighter]

  return (
    <FormControl>
      <FormControl.Label visuallyHidden>Node content</FormControl.Label>
      <ContentEditor
        className={className}
        content={content}
        onUpdate={onUpdate}
        placeholder={placeholder}
        extensions={allExtensions}
        inputLabelId={inputLabelId}
        compact={compact}
        readonly={readonly}
      />
      {!compact && !readonly && (
        <FormControl.Caption className={styles.caption}>
          Type @ or {'{{'} to see a list of nodes that can be referenced.
        </FormControl.Caption>
      )}
    </FormControl>
  )
}

try{ ContentEditorWithAutocomplete.displayName ||= 'ContentEditorWithAutocomplete' } catch {}