import {SIDE_PANEL_VIEW_TYPES, VIEW_TYPES} from '../state/loops-state'
import {LOOP_PATH} from './constants'

export function loopURL(loopID: string) {
  return `${LOOP_PATH}/${loopID}`
}

export function nodeURL(loopID: string, nodeID: string): string {
  const loopPath = loopURL(loopID)
  const params = new URLSearchParams()
  params.set('focusedNode', nodeID)
  params.set('view', VIEW_TYPES.CANVAS)
  params.set('sidePanel', SIDE_PANEL_VIEW_TYPES.NODE)
  return `${loopPath}?${params.toString()}`
}
