import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import {getLoopQueryKey} from '../queries/use-loop'
import type {Loop} from '../../types/app'
import type {Result} from '../../service/result'
import {draftVersion, latestVersion} from '../../utils/versions'
import {loopVersionsQueryKey} from '../queries/use-loop-versions'
import type {Version} from '../../types/version'

export function useSaveLoop() {
  const queryClient = useQueryClient()
  const loopsService = useLoopsService()

  return useMutation<Result<Loop>, Error, string | Loop>({
    mutationFn: async (loopOrID: string | Loop) => {
      return await loopsService.saveLoop(loopOrID)
    },
    onSuccess: result => {
      if (!result.success || !result.data) return

      const loopID = result.data.id

      // add the new version to the versions list
      const currentVersions = queryClient.getQueryData<Version[]>(loopVersionsQueryKey(loopID))
      if (currentVersions && result.data.version) {
        const newVersion: Version = {
          id: `${loopID}-${result.data.version}`, // Use actual version data
          loopID,
          version: result.data.version,
          updatedAt: result.data.updatedAt,
        }
        const updatedVersions = [newVersion, ...currentVersions]
        queryClient.setQueryData(loopVersionsQueryKey(loopID), updatedVersions)
      }

      // refetch list of versions to ensure we have the correct server state
      queryClient.invalidateQueries({queryKey: loopVersionsQueryKey(loopID)})

      // update cached loops
      queryClient.setQueryData(getLoopQueryKey(loopID, draftVersion), result.data)
      queryClient.setQueryData(getLoopQueryKey(loopID, latestVersion), result.data)
      if (result.data.version) {
        queryClient.setQueryData(getLoopQueryKey(loopID, result.data.version), result.data)
      }
    },
    onError: (_error, loopOrID, context: unknown) => {
      const loopID = typeof loopOrID === 'string' ? loopOrID : loopOrID.id
      // If the mutation fails, roll back to the previous state
      const typedContext = context as {previousDraftLoop?: Loop; previousLatestLoop?: Loop} | undefined
      if (typedContext?.previousDraftLoop) {
        queryClient.setQueryData(getLoopQueryKey(loopID, draftVersion), typedContext.previousDraftLoop)
      }
      if (typedContext?.previousLatestLoop) {
        queryClient.setQueryData(getLoopQueryKey(loopID, latestVersion), typedContext.previousLatestLoop)
      }
    },
  })
}
