import type {ChangeEvent, ComponentProps} from 'react'
import {Textarea} from '@primer/react'
import {useControlledInput} from '../../hooks/use-controlled-input'

interface TextAreaProps extends Omit<ComponentProps<typeof Textarea>, 'onChange' | 'value'> {
  value?: string
  onChange?: (event: ChangeEvent<HTMLTextAreaElement>) => void
}

export function TextArea(props: TextAreaProps) {
  const {value: controlledValue, onChange, ...restProps} = props
  const {value, onChange: handleChange} = useControlledInput<HTMLTextAreaElement>(controlledValue, onChange)

  return <Textarea {...restProps} value={value} onChange={handleChange} />
}

try{ TextArea.displayName ||= 'TextArea' } catch {}