import {sendEvent} from '@github-ui/hydro-analytics'
import {Button, type ButtonProps} from '@primer/react'
import {useLoopsDispatch} from '../../contexts/LoopsStateProvider'
import {useSaveLoop} from '../../hooks/mutations/use-save-loop'
import {useGetLoop} from '../../hooks/use-get-loop'
import {useSelectedVersion} from '../../hooks/use-selected-version'
import {draftVersion} from '../../utils/versions'

export function RestoreVersionButton({
  size,
  text = 'Restore Version',
  variant,
}: {
  size?: ButtonProps['size']
  text?: string
  variant?: ButtonProps['variant']
}) {
  const {selectedVersion, isLatest} = useSelectedVersion()
  const {getLoop} = useGetLoop()
  const {mutateAsync: saveLoop, isPending: isRestorePending} = useSaveLoop()
  const dispatch = useLoopsDispatch()

  if (isLatest) return null

  const handleRestoreVersion = async () => {
    sendEvent('dotcom_chat.activate', {target: 'LOOP_RESTORE_VERSION', mode: 'loops'})
    if (!selectedVersion || isRestorePending) return

    const loop = getLoop(selectedVersion)
    if (!loop) return

    const newLoop = await saveLoop(loop)
    if (newLoop.success && newLoop.data.version) {
      // When a version gets restored, we set the selected version to be 'draft' to point to the most recent loop.
      dispatch({type: 'SET_VERSION', version: draftVersion})
    }
  }

  return (
    <Button onClick={handleRestoreVersion} size={size} variant={variant} loading={isRestorePending}>
      {text}
    </Button>
  )
}

try{ RestoreVersionButton.displayName ||= 'RestoreVersionButton' } catch {}