import {useEffect, useMemo, useRef} from 'react'
import {IconButton} from '@primer/react'
import {XIcon} from '@primer/octicons-react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {Chat} from './chat/Chat'
import styles from './SidePanel.module.css'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports, no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import {useLayoutContext} from '@github-ui/pacer/Layout/layout-context'
import {useLoopsStateLens, useLoopsDispatch} from '../contexts/LoopsStateProvider'
import {clsx} from 'clsx'
import {TabList} from '@github-ui/pacer/TabList'
import {useIsReadonly} from '../hooks/use-is-readonly'
import {ReadonlyAboutPanel} from './ReadonlyAboutPanel'
import {CompactNodePanel} from './nodes/compact/CompactNodePanel'
import {useLoopLens} from '../hooks/use-loop-lens'
import type {SidePanelViewType} from '../state/loops-state'

type Tab = {
  id: SidePanelViewType
  label: string
}

const aboutTab: Tab = {id: 'about', label: 'About'}
const chatTab: Tab = {id: 'chat', label: 'Chat'}
const nodeTab: Tab = {id: 'node', label: 'Node'}

interface SidePanelProps {
  nodeId?: string | null
  isMobileView?: boolean
}

export const ToggleButton = () => {
  const {toggleSecondaryColumn} = useLayoutContext()
  return <IconButton aria-label={'Toggle Side Panel'} icon={XIcon} onClick={toggleSecondaryColumn} />
}

export function SidePanel({nodeId}: {nodeId?: string | null}) {
  const {layoutBreakpoint} = useLayoutContext()
  return <SidePanelImpl isMobileView={layoutBreakpoint} nodeId={nodeId} />
}

function SidePanelImpl({isMobileView, nodeId}: SidePanelProps) {
  const {streamingMessage, isWaitingOnCopilot} = useChatState()
  const isStreaming = streamingMessage || isWaitingOnCopilot
  const activeView = useLoopsStateLens(s => s.sidePanelView)
  const dispatch = useLoopsDispatch()
  const isFirstRender = useRef(true)
  const {isReadonly, reason} = useIsReadonly()
  const loopTitle = useLoopLens(loop => loop?.title, 'latest')

  const tabs = useMemo(() => {
    const visibleTabs: Tab[] = []
    if (isReadonly) {
      if (reason === 'shared') visibleTabs.push(aboutTab)
    } else {
      visibleTabs.push(chatTab)
    }

    visibleTabs.push(nodeTab)
    return visibleTabs
  }, [isReadonly, reason])

  useEffect(() => {
    isFirstRender.current = false
  }, [])

  useEffect(() => {
    if (isStreaming) {
      dispatch({type: 'SET_SIDE_PANEL_VIEW', view: 'chat'})
    }
  }, [isStreaming, dispatch])

  useEffect(() => {
    if (isFirstRender.current) return

    if (nodeId && !isStreaming) {
      dispatch({type: 'SET_SIDE_PANEL_VIEW', view: 'node'})
    }
  }, [isStreaming, nodeId, dispatch])

  useEffect(() => {
    // if the list of tabs changes and the current active view is no longer valid, switch to the first available tab
    const firstTabId = tabs[0]?.id
    if (firstTabId && !tabs.find(t => t.id === activeView)) {
      dispatch({type: 'SET_SIDE_PANEL_VIEW', view: firstTabId})
    }
  }, [activeView, dispatch, tabs])

  const handleTabChange = (view: SidePanelViewType) => {
    const viewToTarget: Record<typeof view, string> = {
      chat: 'PANEL_SELECT_CHAT',
      node: 'PANEL_SELECT_NODE',
      about: 'PANEL_SELECT_ABOUT',
    }
    dispatch({type: 'SET_SIDE_PANEL_VIEW', view})
    sendEvent('dotcom_chat.activate', {
      target: viewToTarget[view],
      mode: 'loops',
    })
  }

  return (
    <div className={styles.container}>
      <div className={clsx(styles.panelHeader, styles.v2)}>
        <div className={styles.navigation}>
          <h1 className="sr-only">{loopTitle || 'Untitled Loop'}</h1>
          <TabList
            tabs={tabs}
            activeTab={activeView}
            onTabChange={(id: string) =>
              id === 'chat' || id === 'node' || id === 'about' ? handleTabChange(id) : null
            }
            ariaLabel="Loops panel"
            className={styles.buttonlist}
          />
          {isMobileView && <ToggleButton />}
        </div>
        <h2 className="sr-only">{activeView === 'chat' ? 'Chat' : 'Node details'}</h2>
      </div>
      <div className={clsx(styles.content, styles.v2)}>
        {activeView === 'chat' ? (
          <Chat isMobileView={isMobileView} />
        ) : activeView === 'node' ? (
          <CompactNodePanel key={nodeId || 'empty'} nodeId={nodeId} isMobile={isMobileView} />
        ) : (
          <ReadonlyAboutPanel />
        )}
      </div>
    </div>
  )
}

try{ ToggleButton.displayName ||= 'ToggleButton' } catch {}
try{ SidePanel.displayName ||= 'SidePanel' } catch {}
try{ SidePanelImpl.displayName ||= 'SidePanelImpl' } catch {}