import {useQueryClient} from '@github-ui/react-query'
import type {Execution} from '../types/execution'
import {useExecutionQueryKey} from './queries/use-execution'

/**
 * Hook that returns a function to get the latest execution for the current loop
 * from the react-query cache without triggering a refetch. Useful inside
 * callbacks where we want the current value but do not want to subscribe the component to
 * changes.
 */
export function useGetExecution() {
  const queryClient = useQueryClient()
  const queryKey = useExecutionQueryKey()

  const getExecution = () => {
    return queryClient.getQueryData<Execution | null>(queryKey) ?? null
  }

  return {getExecution}
}
