import {useState} from 'react'
import {useLoopsService} from '../contexts/LoopsServiceProvider'
import {useAppContext} from '../contexts/AppContextProvider'
import {logError} from '../utils/console'
import {getLoopGraph} from '../utils/loops'
import {useProgressHandler} from './use-progress-handler'
import type {Loop, LoopGraph} from '../types/app'
import {useCreateExecution} from './mutations/use-create-execution'
import type {Execution} from '../types/execution'
import {executionQueryKey} from './queries/use-execution'
import {useQueryClient} from '@github-ui/react-query'
import {useCancelExecutionMutation} from './mutations/use-execution-mutations'
import {ErrorResult, SuccessResult} from '../service/result'
import {getInputNodeDefaults} from '../utils/input-detection'
import {useSaveLoop} from './mutations/use-save-loop'
import {useLoopDraftStatus} from './use-loop-draft-status'
import {draftVersion, latestVersion} from '../utils/versions'
import {useGetExecution} from './use-get-execution'
import {validateLoop} from '../service/validate-loop'
import {useGetLoop} from './use-get-loop'

function getDownstreamNodeIds(graph: LoopGraph, nodeId: string): string[] {
  const downstream = new Set(graph.edges.filter(e => e.from === nodeId).map(e => e.to))
  for (const n of downstream) {
    for (const node of getDownstreamNodeIds(graph, n)) {
      downstream.add(node)
    }
  }
  downstream.add(nodeId)
  return [...downstream]
}

function copyExecutionWithExcludedNodes(execution: Execution, excludedNodeIds: string[]): Execution {
  const newNodes = Object.fromEntries(Object.entries(execution.nodes).filter(([id]) => !excludedNodeIds.includes(id)))

  return {
    ...execution,
    nodes: newNodes,
  }
}

function mergeInputValuesWithOverrides(loop: Loop, inputOverrides?: Record<string, string>): Record<string, string> {
  // Determine input values: merge overrides with defaults
  const defaults = getInputNodeDefaults(loop)
  const inputValues = {...defaults}

  // Apply overrides, using default values for empty overrides
  if (inputOverrides) {
    for (const [overrideNodeId, overrideValue] of Object.entries(inputOverrides)) {
      if (overrideValue && overrideValue.trim().length > 0) {
        inputValues[overrideNodeId] = overrideValue
      }
      // If override is empty, keep the default value that's already in inputValues
    }
  }

  return inputValues
}

export function useRunPipeline() {
  const service = useLoopsService()
  const queryClient = useQueryClient()
  const [isPreparing, setIsPreparing] = useState(false)
  const {availableModels} = useAppContext()

  const {createProgressHandler} = useProgressHandler()
  const {mutateAsync: createExecution} = useCreateExecution()
  const {mutateAsync: cancelExecution} = useCancelExecutionMutation()
  const {mutateAsync: saveLoop} = useSaveLoop()
  const {hasChanges} = useLoopDraftStatus()
  const {getExecution} = useGetExecution()
  const {getLoop} = useGetLoop()

  const runPipeline = async (loop: Loop, nodeId?: string, inputOverrides?: Record<string, string>) => {
    setIsPreparing(true)

    try {
      const hasValidationErrors = validateLoop(loop, {availableModels}).length > 0
      if (hasValidationErrors) {
        setIsPreparing(false)
        return
      }

      let loopToRun = loop
      let versionToRun: string = draftVersion
      if (hasChanges) {
        const saveResult = await saveLoop(loop)
        if (!saveResult.success) {
          throw new Error('Failed to save loop before execution')
        }

        loopToRun = saveResult.data
      } else if (loopToRun.version === draftVersion) {
        // Handle an edge case where the draft version is forked from the current saved version,
        // but in a deep comparison it is the same as the current saved version.
        // We only allow running the draft version, but we also don't want to save a new version.
        const latestLoop = getLoop(latestVersion)
        if (latestLoop) {
          loopToRun = latestLoop
        }
      }

      if (!loopToRun.version) {
        throw new Error('Loop version is not set on the loop to run.')
      }

      if (loopToRun.version === draftVersion) {
        throw new Error('Draft version cannot be run directly.')
      }

      versionToRun = loopToRun.version

      const inputValues = mergeInputValuesWithOverrides(loopToRun, inputOverrides)

      // Create a new execution
      let newExecution: Execution
      const currentExecution = getExecution()

      if (nodeId && currentExecution) {
        const graph = getLoopGraph(loopToRun.nodes)
        const upstreamNodeIds = getDownstreamNodeIds(graph, nodeId)
        const copiedExecution = copyExecutionWithExcludedNodes(currentExecution, upstreamNodeIds)

        newExecution = await createExecution({
          execution: {
            ...copiedExecution,
            inputValues,
          },
          version: versionToRun,
        })
      } else {
        // Full execution: create a fresh execution with input values
        newExecution = await createExecution({
          execution: Object.keys(inputValues).length > 0 ? {inputValues} : undefined,
          version: versionToRun,
        })
      }

      // Create a progress handler that uses mutations
      const progressHandler = createProgressHandler(loop.id, versionToRun)
      const handleGetExecution = (loopID: string, version: string) => {
        const execution = queryClient.getQueryData<Execution | null>(executionQueryKey(loopID, version)) ?? null
        return Promise.resolve(execution ? SuccessResult(execution) : ErrorResult('execution not found'))
      }

      setIsPreparing(false)
      await service.runPipeline(loopToRun, newExecution.id, progressHandler, handleGetExecution)
    } catch (error) {
      setIsPreparing(false)
      logError('Error running pipeline:', error)
      throw error
    }
  }

  const stopPipeline = () => {
    const currentExecution = getExecution()
    if (!currentExecution) return

    service.stopPipeline(currentExecution.id, () => {
      cancelExecution({loopID: currentExecution.loopID, version: currentExecution.loopVersion})
    })
  }

  return {runPipeline, stopPipeline, isPreparing}
}
