import {useQuery} from '@github-ui/react-query'
import {useParams} from '@github-ui/react-router'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import type {Version} from '../../types/version'

export const LOOP_VERSIONS_QUERY_KEY = 'loop-versions'

export function loopVersionsQueryKey(loopID: string) {
  return [LOOP_VERSIONS_QUERY_KEY, loopID]
}

export function useLoopVersions<T = Version[] | null>(selector?: (versions: Version[] | undefined | null) => T) {
  const {loopID} = useParams()
  const service = useLoopsService()

  return useQuery({
    queryKey: loopVersionsQueryKey(loopID ?? ''),
    queryFn: async () => {
      if (!loopID) return null

      const result = await service.getLoopVersions(loopID)
      if (!result.success) return null

      return result.data
    },
    enabled: !!loopID,
    ...(selector && {select: selector}),
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}
