// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {ModelPickerDesign} from '@github-ui/copilot-chat/components/ModelPicker'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {CopilotChatModel} from '@github-ui/copilot-chat/utils/copilot-chat-types'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useDefaultModel} from '@github-ui/copilot-chat/utils/models'
import {useAppContext} from '../../contexts/AppContextProvider'

interface ModelPickerProps {
  onUpdateModel: (model: string) => void
  selectedModelName: string
}

function createPlaceholderModel(invalidModelId: string): CopilotChatModel {
  return {
    id: invalidModelId,
    name: `${invalidModelId} (unavailable)`,
    displayName: `${invalidModelId} (unavailable)`,
    hasLimitedCapabilities: true,
    isThirdParty: false,
    version: '',
    vendor: '',
    preview: false,
    model_picker_enabled: false,
    capabilities: {
      type: 'chat',
      family: '',
      limits: {max_prompt_tokens: 0},
      supports: {},
      tokenizer: '',
    },
  }
}

export function ModelPicker({onUpdateModel, selectedModelName}: ModelPickerProps) {
  const {availableModels} = useAppContext()
  const defaultModel = useDefaultModel(availableModels)
  const foundModel = availableModels?.find(model => model.id === selectedModelName)

  const selectedModel =
    selectedModelName && !foundModel ? createPlaceholderModel(selectedModelName) : foundModel ?? defaultModel

  const handleUpdateModel = (model: CopilotChatModel) => {
    onUpdateModel(model.id)
  }

  if (!availableModels) return null

  return (
    <ModelPickerDesign
      models={availableModels}
      selectedModel={selectedModel}
      onModelPicked={handleUpdateModel}
      disabled={false}
      type={'global'}
      variant={'default'}
    />
  )
}

try{ ModelPicker.displayName ||= 'ModelPicker' } catch {}