import {ViewPlugin, Decoration} from '@codemirror/view'
import type {DecorationSet, ViewUpdate, EditorView} from '@codemirror/view'
import type {Range} from '@codemirror/state'
import type {Node} from '../../types/app'

/**
 * Creates a CodeMirror extension that highlights valid node references in the format {{nodeId}}
 */
export function createNodeReferenceHighlighter(getPipelineNodes: () => Node[], nodeId?: string) {
  const nodeReferenceDecoration = Decoration.mark({
    class: 'cm-node-reference',
  })

  return ViewPlugin.fromClass(
    class {
      decorations: DecorationSet

      constructor(view: EditorView) {
        this.decorations = this.buildDecorations(view)
      }

      update(update: ViewUpdate) {
        if (update.docChanged || update.viewportChanged) {
          this.decorations = this.buildDecorations(update.view)
        }
      }

      buildDecorations(view: EditorView) {
        const decorations: Array<Range<Decoration>> = []
        const nodes = getPipelineNodes()
        const validNodeIds = new Set(nodes.map(node => node.id).filter(id => id !== nodeId))

        // Regex to match {{nodeId}} patterns
        const nodeReferenceRegex = /\{\{([^}]+)\}\}/g

        for (const {from, to} of view.visibleRanges) {
          const text = view.state.doc.sliceString(from, to)
          let match

          while ((match = nodeReferenceRegex.exec(text)) !== null) {
            const nodeIdInReference = match[1]

            // Only highlight if the nodeId is valid and not the current node
            if (nodeIdInReference && validNodeIds.has(nodeIdInReference)) {
              const start = from + match.index
              const end = start + match[0].length
              decorations.push(nodeReferenceDecoration.range(start, end))
            }
          }
        }

        return Decoration.set(decorations)
      }
    },
    {
      decorations: v => v.decorations,
    },
  )
}
