import {
  KebabHorizontalIcon,
  ShareAndroidIcon,
  VersionsIcon,
  ChevronRightIcon,
  DuplicateIcon,
  PencilIcon,
  HistoryIcon,
  TrashIcon,
  CopyIcon,
  AlertIcon,
} from '@primer/octicons-react'
import {
  ActionList,
  ActionMenu,
  IconButton,
  Dialog,
  FormControl,
  RadioGroup,
  Radio,
  Button,
  ConfirmationDialog,
} from '@primer/react'
import {useCallback, useRef, useState} from 'react'
import {useExecuteButton} from '../../hooks/use-execute-button'
import {useIsReadonly} from '../../hooks/use-is-readonly'
import {useLoopID} from '../../state/lenses'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import {useLoopLens} from '../../hooks/use-loop-lens'
import {copyText} from '@github-ui/copy-to-clipboard'
import {useQueryClient} from '@github-ui/react-query'
import {getLoopQueryKey} from '../../hooks/queries/use-loop'
import {draftVersion} from '../../utils/versions'
import type {Loop} from '../../types/app'
import {useLoopVersions} from '../../hooks/queries/use-loop-versions'
import {useOneTimeBanner} from '../../hooks/use-one-time-banner'
import styles from '../LoopShareButton.module.css'
import {InputPickerPanel} from '../modals/InputPickerPanel'
import {VersionList} from './VersionList'
import {useDuplicateLoop} from '../../hooks/use-duplicate-loop'
import {RenameDialog} from '../RenameDialog'
import {useGetLoop} from '../../hooks/use-get-loop'
import {useDeleteLoop} from '../../hooks/mutations/use-delete-loop'
import {useNavigate} from '@github-ui/react-router'
import {LOOPS_PATH} from '../../utils/constants'
import {sendEvent} from '@github-ui/hydro-analytics'
import type {SharingMode} from '../../types/sharing'
import {reportAbusePath} from '@github-ui/paths'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'

export function MobileHeaderMenu() {
  const actionMenuButtonRef = useRef<HTMLButtonElement>(null)
  const {showInputPicker, handleInputPickerClose, handleInputPickerRun} = useExecuteButton()

  const {isReadonly, isLoading: isReadonlyLoading, reason} = useIsReadonly()
  const {ownerLogin, owned, loopURL} = useLoopLens(l => ({
    owned: l?.owned,
    ownerLogin: l?.ownerLogin,
    // this avoids accessing window during a render
    loopURL: window.location.origin + window.location.pathname,
  }))

  const [shareDialogOpen, setShareDialogOpen] = useState(false)
  const [sharingMode, setSharingMode] = useState<SharingMode>('only-me')
  const loopID = useLoopID()
  const loopsService = useLoopsService()
  const loopVisibility = useLoopLens(loop => loop?.visibility)
  const queryClient = useQueryClient()
  const {showBanner: showLinkCopiedBanner} = useOneTimeBanner('linkCopied')

  const openShareDialog = useCallback(() => {
    if (loopVisibility === 'public') {
      setSharingMode('anyone')
    } else {
      setSharingMode('only-me')
    }
    setShareDialogOpen(true)
  }, [loopVisibility])

  const closeShareDialog = useCallback(() => setShareDialogOpen(false), [])
  const handleSharingModeChange = useCallback((value: string | null) => {
    if (!value) return
    setSharingMode(value as SharingMode)
  }, [])

  const copyShareLink = useCallback(async () => {
    if (loopID && sharingMode === 'anyone') {
      const loopsUrl = `${window.location.origin}/copilot/l/${loopID}`
      await copyText(loopsUrl)
      showLinkCopiedBanner('Link copied to your clipboard.')
      closeShareDialog()
    }
  }, [loopID, sharingMode, closeShareDialog, showLinkCopiedBanner])

  const handleSaveShare = useCallback(async () => {
    if (!loopID) return
    let newVisibility: 'public' | 'private'
    if (sharingMode === 'anyone') {
      await loopsService.shareLoop(loopID)
      newVisibility = 'public'
    } else {
      await loopsService.unshareLoop(loopID)
      newVisibility = 'private'
    }
    const queryKey = getLoopQueryKey(loopID, draftVersion)
    queryClient.setQueryData(queryKey, (oldData: Loop | null | undefined) => {
      if (oldData && typeof oldData === 'object') {
        return {...oldData, visibility: newVisibility}
      }
      return oldData
    })
    if (newVisibility === 'public') {
      copyShareLink()
    }
    closeShareDialog()
  }, [loopID, sharingMode, loopsService, queryClient, copyShareLink, closeShareDialog])

  const {data: versions, isLoading: versionsLoading} = useLoopVersions()
  const sortedVersions = versions?.sort((a, b) => a.updatedAt - b.updatedAt).filter(v => v.version !== draftVersion)

  // Additional actions state
  const duplicateLoop = useDuplicateLoop()
  const {getLoop} = useGetLoop()
  const {mutateAsync: deleteLoop} = useDeleteLoop()
  const navigate = useNavigate()
  const [showRenameDialog, setShowRenameDialog] = useState(false)
  const [showDeleteDialog, setShowDeleteDialog] = useState(false)

  const handleDuplicate = useCallback(async () => {
    await duplicateLoop()
    sendEvent('dotcom_chat.activate', {target: 'MOBILE_LOOP_DUPLICATE', mode: 'loops'})
  }, [duplicateLoop])

  const handleOpenRename = useCallback(() => {
    setShowRenameDialog(true)
    sendEvent('dotcom_chat.activate', {target: 'MOBILE_LOOP_RENAME_OPEN', mode: 'loops'})
  }, [])

  const copyLoopToClipboard = () => {
    const draftLoop = getLoop()
    if (!draftLoop) return

    const fieldsToCopy = {
      title: draftLoop.title,
      description: draftLoop.description,
      nodes: draftLoop.nodes,
    }

    const pipelineJson = JSON.stringify(fieldsToCopy, null, 2)
    navigator.clipboard.writeText(pipelineJson)
    sendEvent('dotcom_chat.activate', {target: 'HEADER_JSON_COPY', mode: 'loops'})
  }
  const handleRestoreVersion = useCallback(async () => {
    const loop = getLoop()
    if (!loop) return
    // Restoring version means promoting the viewed version to latest; service has restoreLoopVersion
    await loopsService.restoreLoopVersion(loop)
    sendEvent('dotcom_chat.activate', {target: 'MOBILE_LOOP_RESTORE_VERSION', mode: 'loops'})
  }, [getLoop, loopsService])

  const handleOpenDelete = useCallback(() => {
    setShowDeleteDialog(true)
  }, [])

  const handleConfirmDelete = useCallback(async () => {
    const loop = getLoop()
    if (!loop) return
    await deleteLoop(loop.id)
    sendEvent('dotcom_chat.activate', {target: 'MOBILE_LOOP_DELETE', mode: 'loops'})
    navigate(LOOPS_PATH)
  }, [deleteLoop, getLoop, navigate])

  const handleCloseDelete = useCallback(() => setShowDeleteDialog(false), [])

  if (isReadonlyLoading) return null

  return (
    <>
      <ActionMenu>
        <ActionMenu.Anchor>
          <IconButton aria-label="Loop actions" icon={KebabHorizontalIcon} ref={actionMenuButtonRef} />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay>
          <ActionList>
            {/* Duplicate available for owners and shared/previousVersion readonly views */}
            <ActionList.Item onSelect={handleDuplicate}>
              <ActionList.LeadingVisual>
                <DuplicateIcon />
              </ActionList.LeadingVisual>
              Duplicate
            </ActionList.Item>
            {/* Rename only if editable (not readonly) */}
            {!isReadonly && (
              <ActionList.Item onSelect={handleOpenRename}>
                <ActionList.LeadingVisual>
                  <PencilIcon />
                </ActionList.LeadingVisual>
                Rename
              </ActionList.Item>
            )}
            {/* Restore only when viewing previous version */}
            {isReadonly && reason === 'previousVersion' && (
              <ActionList.Item onSelect={handleRestoreVersion}>
                <ActionList.LeadingVisual>
                  <HistoryIcon />
                </ActionList.LeadingVisual>
                Restore version
              </ActionList.Item>
            )}
            {!isReadonly && (
              <ActionList.Item onSelect={openShareDialog}>
                <ActionList.LeadingVisual>
                  <ShareAndroidIcon />
                </ActionList.LeadingVisual>
                Share
              </ActionList.Item>
            )}
            <ActionList.Item onSelect={copyLoopToClipboard}>
              <ActionList.LeadingVisual>
                <CopyIcon />
              </ActionList.LeadingVisual>
              Copy JSON
            </ActionList.Item>
            {!versionsLoading && sortedVersions && sortedVersions.length > 0 && (
              <ActionMenu>
                <ActionMenu.Anchor>
                  <ActionList.Item>
                    <ActionList.LeadingVisual>
                      <VersionsIcon />
                    </ActionList.LeadingVisual>
                    Versions
                    <ActionList.TrailingVisual>
                      <ChevronRightIcon />
                    </ActionList.TrailingVisual>
                  </ActionList.Item>
                </ActionMenu.Anchor>
                <ActionMenu.Overlay align="end">
                  <VersionList />
                </ActionMenu.Overlay>
              </ActionMenu>
            )}
            {copilotFeatureFlags.loopsAbusePrevention && ownerLogin && !owned && loopURL && (
              <>
                <ActionList.Divider />
                <ActionList.LinkItem
                  variant="danger"
                  href={reportAbusePath({
                    report: `${ownerLogin} (User)`,
                    contentURL: loopURL,
                  })}
                >
                  <ActionList.LeadingVisual>
                    <AlertIcon />
                  </ActionList.LeadingVisual>
                  Report
                </ActionList.LinkItem>
              </>
            )}
            {/* Delete only if editable (not readonly) */}
            {!isReadonly && (
              <>
                <ActionList.Divider />
                <ActionList.Item variant="danger" onSelect={handleOpenDelete}>
                  <ActionList.LeadingVisual>
                    <TrashIcon />
                  </ActionList.LeadingVisual>
                  Delete
                </ActionList.Item>
              </>
            )}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>

      {shareDialogOpen && (
        <Dialog title="Share loop" onClose={closeShareDialog} returnFocusRef={actionMenuButtonRef} width="large">
          <div>
            <RadioGroup name="sharing-mode" onChange={handleSharingModeChange}>
              <RadioGroup.Label visuallyHidden>Sharing options</RadioGroup.Label>
              <FormControl>
                <Radio value="anyone" checked={sharingMode === 'anyone'} />
                <FormControl.Label className={styles.radioLabel}>Anyone with link</FormControl.Label>
                <FormControl.Caption>Everyone can access your loop through the link</FormControl.Caption>
              </FormControl>
              <FormControl className={styles.radioOption}>
                <Radio value="only-me" checked={sharingMode === 'only-me'} />
                <FormControl.Label className={styles.radioLabel}>Only me</FormControl.Label>
                <FormControl.Caption>Only you have access to your loop</FormControl.Caption>
              </FormControl>
            </RadioGroup>
            <hr className={styles.divider} />
            <div className={styles.actions}>
              <Button onClick={copyShareLink} inactive={loopVisibility === 'private'}>
                Copy link
              </Button>
              <Button variant="primary" onClick={handleSaveShare}>
                Save
              </Button>
            </div>
          </div>
        </Dialog>
      )}

      <InputPickerPanel isOpen={showInputPicker} onClose={handleInputPickerClose} onRun={handleInputPickerRun} />
      <RenameDialog isOpen={showRenameDialog} onClose={() => setShowRenameDialog(false)} />
      {showDeleteDialog && (
        <ConfirmationDialog
          title="Delete loop"
          onClose={gesture => {
            if (gesture === 'confirm') {
              handleConfirmDelete()
            }
            handleCloseDelete()
          }}
          confirmButtonContent="Delete"
          confirmButtonType="danger"
        >
          Are you sure you want to delete this loop? This action cannot be undone.
        </ConfirmationDialog>
      )}
    </>
  )
}

try{ MobileHeaderMenu.displayName ||= 'MobileHeaderMenu' } catch {}