// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useChatStateValue} from '@github-ui/copilot-chat/CopilotChatContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {makeLoopNodeRef, referenceID} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {useMemo} from 'react'
import {useLoopsDispatch} from '../contexts/LoopsStateProvider'
import {nodeURL} from '../utils/urls'
import {useGetLoop} from './use-get-loop'

/**
 * Hook for adding/removing loop-node references to chat with single selection logic.
 * Ensures only one loop-node reference can be selected at a time.
 */
export function useAddLoopNodeReference() {
  const manager = useChatManager()
  const currentReferences = useChatStateValue('currentReferences')
  const dispatch = useLoopsDispatch()
  const {getLoop} = useGetLoop()

  const addLoopNodeReference = (nodeId: string, nodeTitle: string, source: string) => {
    const loopID = getLoop()?.id
    if (!loopID) return

    // For loop-node references, ensure only one can be selected at a time
    const existingLoopNodeRefs = currentReferences.filter(ref => ref.type === 'loop-node')
    if (existingLoopNodeRefs.length > 0) {
      manager.removeReferences(existingLoopNodeRefs)
    }

    const url = nodeURL(loopID, nodeId)
    const loopNodeRef = makeLoopNodeRef(nodeId, nodeTitle, url)
    dispatch({type: 'SET_SIDE_PANEL_VIEW', view: 'chat'})
    manager.addReference(loopNodeRef, source)
  }

  const toggleLoopNodeReference = (nodeId: string, nodeTitle: string, source: string) => {
    const expectedRef = makeLoopNodeRef(nodeId, nodeTitle)
    const expectedRefId = referenceID(expectedRef)
    const currentNodeRef = currentReferences.find(ref => ref.type === 'loop-node' && referenceID(ref) === expectedRefId)

    if (currentNodeRef) {
      manager.removeReference(currentNodeRef)
    } else {
      addLoopNodeReference(nodeId, nodeTitle, source)
    }
  }

  const isNodeReferenced = useMemo(() => {
    return (nodeId: string, nodeTitle: string) => {
      const expectedRef = makeLoopNodeRef(nodeId, nodeTitle)
      const expectedRefId = referenceID(expectedRef)
      return currentReferences.some(ref => ref.type === 'loop-node' && referenceID(ref) === expectedRefId)
    }
  }, [currentReferences])

  return {addLoopNodeReference, toggleLoopNodeReference, isNodeReferenced}
}
