import {clsx} from 'clsx'
import {Spinner} from '@primer/react'
import {useTheme} from '@primer/styled-react'
import {EyeIcon} from '@primer/octicons-react'
import {forwardRef, type KeyboardEvent, type MouseEvent} from 'react'

import styles from './CompactNode.module.css'
import {NodeType as NodeTypeComponent} from '../NodeType'
import {NodeReferenceButton} from '../../controls/NodeReferenceButton'
import {AlertIcon} from '../../CustomIcon'
import {
  nodeDefinition,
  useNode,
  useNodeIndicatorStatus,
  useNodeRunning,
  useNodeType,
  useVirtualNodeIndicatorStatus,
  type Status,
} from '../../../state/lenses'
import type {NodeType as NodeTypeProps} from '../../../types/app'
import {useLoopsStateLens} from '../../../contexts/LoopsStateProvider'
import {useLoopLens} from '../../../hooks/use-loop-lens'
import {useHasValidationErrors} from '../../../hooks/use-validation-errors'
import {useAddLoopNodeReference} from '../../../hooks/use-add-loop-node-reference'
import {isPostStaffShipFeaturesEnabled} from '../../../utils/feature-flags'
import {useTruncatedText} from '../../../utils/truncate'

interface CompactNodeProps {
  nodeId: string
  className?: string
  hasPredecessors?: boolean
  hasSuccessors?: boolean
  title?: string
  type?: NodeTypeProps
  isPlaceholder?: boolean
  isVirtual?: boolean
  onClick?: (event: MouseEvent<HTMLDivElement>) => void
  onKeyDown?: (event: KeyboardEvent<HTMLDivElement>) => void
  truncatedWidth?: number
}

interface OutputNodeProps {
  className?: string
  onClick?: (event: MouseEvent<HTMLDivElement>) => void
  onKeyDown?: (event: KeyboardEvent<HTMLDivElement>) => void
}

interface IndicatorProps {
  status: Status
}

const InputIndicator = ({status}: IndicatorProps) => (
  <div
    className={clsx(
      styles.indicatorDot,
      styles.topDot,
      status === 'COMPLETED' && styles.completed,
      status === 'ERROR' && styles.error,
    )}
  />
)

const OutputIndicator = ({status}: IndicatorProps) => (
  <div
    className={clsx(
      styles.indicatorDot,
      styles.bottomDot,
      status === 'COMPLETED' && styles.completed,
      status === 'ERROR' && styles.error,
    )}
  >
    <div className={styles.indicatorShadowWrapper}>
      <div className={styles.indicatorShadow} />
    </div>
  </div>
)

function OutputNode({className, onClick, onKeyDown}: OutputNodeProps) {
  const indicatorStatus = useVirtualNodeIndicatorStatus()
  return (
    <div
      className={clsx(styles.compactNode, styles.outputNode, className)}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : -1}
      onClick={onClick}
      onKeyDown={onKeyDown}
    >
      <InputIndicator status={indicatorStatus} />
      <EyeIcon />
      <p className={styles.title}>Output</p>
    </div>
  )
}

export const CompactNode = forwardRef<HTMLDivElement, CompactNodeProps>(function CompactNode(
  {
    nodeId,
    className,
    hasPredecessors,
    hasSuccessors,
    title,
    type,
    isPlaceholder,
    isVirtual,
    onClick,
    onKeyDown,
    truncatedWidth = 180,
  },
  ref,
) {
  const node = useNode(nodeId)
  const isRunning = useNodeRunning(nodeId)
  const theme = useTheme()
  const nodeTitle = useLoopLens(loop => nodeDefinition(nodeId, loop)?.title)
  const nodeType = useNodeType(nodeId)
  const selected = useLoopsStateLens(s => s.focusedNodeId === nodeId)
  const nodeIndicatorStatus: Status = useNodeIndicatorStatus(nodeId)
  const {isNodeReferenced} = useAddLoopNodeReference()

  const isNodeReferenceEnabled = isPostStaffShipFeaturesEnabled()
  const isReferenced = isNodeReferenced(nodeId, nodeTitle || '')
  const effectiveTitle = title || nodeTitle || ''
  const {ref: titleRef, truncated: truncatedTitle} = useTruncatedText(effectiveTitle, truncatedWidth, {
    preferWords: true,
  })

  if (isVirtual) {
    return (
      <OutputNode className={clsx(className, onClick && styles.interactive)} onClick={onClick} onKeyDown={onKeyDown} />
    )
  }
  type = type || nodeType

  return (
    <div className={styles.container}>
      <div
        ref={ref}
        className={clsx(
          styles.compactNode,
          className,
          onClick && styles.interactive,
          selected ? styles.active : null,
          theme.colorScheme?.includes('dark') || theme.colorScheme?.includes('night') ? styles.dark : '',
        )}
        role={onClick ? 'button' : undefined}
        tabIndex={onClick ? 0 : -1}
        onClick={onClick}
        onKeyDown={onKeyDown}
      >
        {hasPredecessors && <InputIndicator status={nodeIndicatorStatus} />}
        {hasSuccessors && <OutputIndicator status={nodeIndicatorStatus} />}
        {isRunning ? <Spinner size="small" /> : <NodeTypeComponent type={type} size="medium" node={node} />}
        <p ref={titleRef as React.RefObject<HTMLParagraphElement | null>} className={styles.title}>
          {truncatedTitle}
        </p>
        <ValidationErrorsIndicator nodeId={nodeId} />
      </div>
      {isNodeReferenceEnabled && !isPlaceholder && (
        <NodeReferenceButton
          className={clsx(styles.nodeReferenceButton, isReferenced && styles.referenced)}
          nodeId={nodeId}
        />
      )}
    </div>
  )
})

function ValidationErrorsIndicator({nodeId}: {nodeId: string}) {
  const hasValidationErrors = useHasValidationErrors(nodeId)

  if (!hasValidationErrors) return null

  return (
    <div className={styles.validationErrorWrapper}>
      <AlertIcon />
    </div>
  )
}

try{ InputIndicator.displayName ||= 'InputIndicator' } catch {}
try{ OutputIndicator.displayName ||= 'OutputIndicator' } catch {}
try{ OutputNode.displayName ||= 'OutputNode' } catch {}
try{ CompactNode.displayName ||= 'CompactNode' } catch {}
try{ ValidationErrorsIndicator.displayName ||= 'ValidationErrorsIndicator' } catch {}