import {ContentEditorWithAutocomplete} from './ContentEditorWithAutocomplete'
import {autocompletion} from '@codemirror/autocomplete'
import type {Extension} from '@codemirror/state'
import {useEffect, useState} from 'react'

/**
 * A ContentEditor with JavaScript syntax highlighting and autocompletion.
 */
export const JSCodeEditor = ({
  className,
  content,
  onUpdate,
  nodeId,
  inputLabelId,
  readonly = false,
}: {
  className?: string
  content: string
  onUpdate?: (content: string) => void
  nodeId: string
  inputLabelId: string
  readonly?: boolean
}) => {
  const [extensions, setExtensions] = useState<Extension[] | undefined>()

  useEffect(() => {
    // Lazy load the JavaScript language support
    const loadJavaScript = async () => {
      const {javascript} = await import('@codemirror/lang-javascript')
      setExtensions([
        autocompletion(),
        javascript({
          jsx: false,
          typescript: false,
        }),
      ])
    }
    void loadJavaScript()
  }, [])

  return (
    <ContentEditorWithAutocomplete
      className={className}
      content={content}
      extensions={extensions}
      inputLabelId={inputLabelId}
      nodeId={nodeId}
      onUpdate={onUpdate}
      placeholder="// JavaScript code goes here"
      readonly={readonly}
    />
  )
}

try{ JSCodeEditor.displayName ||= 'JSCodeEditor' } catch {}