import React from 'react'
import styles from './TabList.module.css'
import {clsx} from 'clsx'

export interface TabListTab {
  id: string
  label: React.ReactNode
  count?: number
  disabled?: boolean
  className?: string
  // Optional analytics payload to attach to the tab button. If provided, it will be
  // serialized and assigned to the `data-analytics-event` attribute so shared
  // analytics code can pick it up on click.
  analyticsEvent?: Record<string, unknown> | string
}

export interface TabListProps {
  tabs: TabListTab[]
  activeTab: string
  onTabChange: (id: string) => void
  ariaLabel?: string
  className?: string
}

export function TabList({tabs, activeTab, onTabChange, ariaLabel, className}: TabListProps) {
  return (
    <div role="tablist" aria-label={ariaLabel} className={clsx(styles.tabList, className)}>
      {tabs.map(tab => {
        const isActive = activeTab === tab.id
        return (
          <button
            key={tab.id}
            id={tab.id}
            role="tab"
            aria-selected={isActive}
            aria-controls={tab.id}
            className={clsx(styles.tabButton, tab.className)}
            type="button"
            disabled={tab.disabled}
            data-analytics-event={
              tab.analyticsEvent
                ? typeof tab.analyticsEvent === 'string'
                  ? tab.analyticsEvent
                  : JSON.stringify(tab.analyticsEvent)
                : undefined
            }
            onClick={tab.disabled ? undefined : () => onTabChange(tab.id)}
          >
            {tab.label}
            {typeof tab.count === 'number' && <span className={styles.tabCounter}>{tab.count}</span>}
          </button>
        )
      })}
    </div>
  )
}

try{ TabList.displayName ||= 'TabList' } catch {}