import {Button} from '@primer/react'
import {sendEvent} from '@github-ui/hydro-analytics'
import styles from './HeaderActions.module.css'
import {useIsReadonly} from '../../hooks/use-is-readonly'
import {RestoreVersionButton} from './RestoreVersionButton'
import {useDuplicateLoop} from '../../hooks/use-duplicate-loop'
import type {ReactNode} from 'react'
import {ExecuteButtonWithModal} from './ExecuteButtonWithModal'

function ReadonlyActions() {
  const duplicateLoop = useDuplicateLoop()
  const {reason, isLoading} = useIsReadonly()

  if (isLoading) {
    return null
  }

  const handleDuplicate = () => {
    duplicateLoop()
    sendEvent('dotcom_chat.activate', {target: 'SHARED_LOOP_DUPLICATE', mode: 'loops'})
  }

  let actionButton: ReactNode | null = null
  if (reason === 'shared') {
    actionButton = (
      <Button variant="default" onClick={handleDuplicate}>
        Duplicate
      </Button>
    )
  } else if (reason === 'previousVersion') {
    actionButton = <RestoreVersionButton variant="default" />
  }

  return <div className={styles.container}>{actionButton}</div>
}

export function HeaderActions() {
  const {isReadonly} = useIsReadonly()
  return (
    <>
      {isReadonly && <ReadonlyActions />}
      <ExecuteButtonWithModal />
    </>
  )
}

try{ ReadonlyActions.displayName ||= 'ReadonlyActions' } catch {}
try{ HeaderActions.displayName ||= 'HeaderActions' } catch {}