import {useState} from 'react'
import {useGetLoop} from './use-get-loop'
import {useRunPipeline} from './use-run-pipeline'
import {useLoopIsRunning} from '../state/lenses'
import {useLoopLens} from './use-loop-lens'
import {getInputNodes} from '../utils/input-detection'
import {sendEvent} from '@github-ui/hydro-analytics'

export function useExecuteButton() {
  const {getLoop} = useGetLoop()
  const {runPipeline, stopPipeline, isPreparing} = useRunPipeline()
  const pipelineRunning = useLoopIsRunning()
  const isLoading = isPreparing || pipelineRunning
  const hasInputNodes = useLoopLens(loop => loop && getInputNodes(loop).length > 0) ?? false
  const [showInputPicker, setShowInputPicker] = useState(false)

  const handleRunButtonClick = () => {
    const loop = getLoop()
    if (!loop) return

    sendEvent('dotcom_chat.activate', {target: 'CANVAS_HEADER_LOOP_RUN', mode: 'loops'})
    runPipeline(loop)
  }

  const handleStopButtonClick = () => {
    sendEvent('dotcom_chat.activate', {target: 'CANVAS_HEADER_LOOP_STOP', mode: 'loops'})
    stopPipeline()
  }

  const handleRunWithInputs = () => {
    setShowInputPicker(true)
  }

  const handleInputPickerRun = (values: Record<string, string>) => {
    const loop = getLoop()
    if (!loop) return

    sendEvent('dotcom_chat.activate', {target: 'CANVAS_HEADER_LOOP_RUN_WITH_INPUTS', mode: 'loops'})
    runPipeline(loop, undefined, values)
    setShowInputPicker(false)
  }

  const handleInputPickerClose = () => {
    setShowInputPicker(false)
  }

  return {
    pipelineRunning: isLoading,
    hasInputNodes,
    showInputPicker,
    handleRunButtonClick,
    handleStopButtonClick,
    handleRunWithInputs,
    handleInputPickerRun,
    handleInputPickerClose,
  }
}
