import type {ChangeEvent, ComponentProps} from 'react'
import {TextInput as PrimerTextInput} from '@primer/react'
import {useControlledInput} from '../../hooks/use-controlled-input'

interface TextInputProps extends Omit<ComponentProps<typeof PrimerTextInput>, 'onChange' | 'value'> {
  value?: string
  onChange?: (event: ChangeEvent<HTMLInputElement>) => void
}

export function TextInput(props: TextInputProps) {
  const {value: controlledValue, onChange, ...restProps} = props
  const {value, onChange: handleChange} = useControlledInput<HTMLInputElement>(controlledValue, onChange)

  return <PrimerTextInput {...restProps} value={value} onChange={handleChange} />
}

try{ TextInput.displayName ||= 'TextInput' } catch {}